pub const Checker = struct {
    pub fn signatureToStringEx(self: *Checker, signature: types.SignatureIndex, enclosingDeclaration: ast_gen.NodeIndex, flags: u32, vc: ?*anyopaque) []const u8 {
        _ = vc;
        if (signature == 0 or signature >= self.signatures.items.len) return "";
        const sig = &self.signatures.items[signature];
        const is_constructor = (sig.flags & types.SignatureFlags.Construct) != 0 and (flags & types.TypeFormatFlags.WriteCallStyleSignature) == 0;
        const use_arrow_style = (flags & types.TypeFormatFlags.WriteArrowStyleSignature) != 0;

        var buf = std.ArrayListUnmanaged(u8).empty;
        defer buf.deinit(self.allocator);

        if (use_arrow_style and is_constructor) {
            buf.appendSlice(self.allocator, "new ") catch {};
        }

        // Parameters
        buf.append(self.allocator, '(') catch {};
        const params = types.parameters(self, signature);
        for (params, 0..) |param_sym, i| {
            if (i > 0) buf.appendSlice(self.allocator, ", ") catch {};
            // Rest parameter prefix
            if (i == params.len - 1 and (sig.flags & types.SignatureFlags.HasRestParameter) != 0) {
                buf.appendSlice(self.allocator, "...") catch {};
            }
            const param_name = self.getSymbolName(param_sym);
            buf.appendSlice(self.allocator, param_name) catch {};
            // Optional marker
            const param_decl = self.getSymbolValueDeclaration(param_sym);
            if (param_decl != 0 and utils.isOptionalDeclaration(self.binder.ast, param_decl)) {
                buf.append(self.allocator, '?') catch {};
            }
            buf.appendSlice(self.allocator, ": ") catch {};
            const param_type = self.getTypeOfParameter(param_sym);
            const type_str = self.typeToString(param_type, enclosingDeclaration, flags, null);
            buf.appendSlice(self.allocator, type_str) catch {};
        }
        buf.append(self.allocator, ')') catch {};

        // Return type
        if (use_arrow_style) {
            buf.appendSlice(self.allocator, " => ") catch {};
        } else {
            buf.appendSlice(self.allocator, ": ") catch {};
        }
        const return_type = self.getReturnTypeOfSignature(sig);
        const return_str = self.typeToString(return_type, enclosingDeclaration, flags, null);
        buf.appendSlice(self.allocator, return_str) catch {};

        const result = buf.toOwnedSlice(self.allocator) catch return "";
        self.ownedStrings.append(self.allocator, result) catch {};
        return result;
    }

    pub fn getExpandedParameters(self: *Checker, signatureIdx: types.SignatureIndex, isJSDoc: bool) []const ast_gen.SymbolIndex {
        _ = isJSDoc;
        const sig = self.signatures.items[signatureIdx];
        return self.signatureParameters.items[sig.parametersStart .. sig.parametersStart + sig.parametersLen];
    }

    /// Port of `checker.go::getContextualTypeForObjectLiteralElement`.
    /// Returns the contextual type for an object literal element (property,
    /// shorthand property, method). The contextual type comes from the
    /// parent object literal's contextual type, looking up the property
    /// name in that type.
    pub fn getContextualTypeForObjectLiteralElement(self: *Checker, element: ast_gen.NodeIndex, contextFlags: u32) types.TypeIndex {
        if (element == 0) return 0;
        // If the element has its own type annotation, use it (except for
        // methods, which delegate to the contextual signature).
        const elem_kind = self.binder.ast.getKind(element);
        if (elem_kind != .MethodDeclaration and elem_kind != .MethodSignature) {
            const type_node_opt: ?ast_gen.NodeIndex = switch (self.binder.ast.getNode(element)) {
                .PropertyAssignment => |p| p.Type,
                .PropertyDeclaration => |p| p.Type,
                .PropertySignature => |p| p.Type,
                .ShorthandPropertyAssignment => null,
                else => null,
            };
            if (type_node_opt) |tn| {
                if (tn != 0) return self.getTypeFromTypeNode(tn);
            }
        }
        // Get the parent object literal and its contextual type.
        const parent = self.binder.ast.getNodeParent(element);
        if (parent == 0) return 0;
        const ctx_type = self.getApparentTypeOfContextualType(parent, contextFlags);
        if (ctx_type == 0) return 0;

        // Look up the element's name in the contextual type.
        const name_node = ast_utils.getPropertyNameOfNode(self.binder.ast, element);
        if (name_node != 0) {
            const name_str = ast_utils.getTextOfNode(self.binder.ast, name_node);
            // Strip quotes from string-literal property names.
            const cleaned_name = if (name_str.len >= 2 and (name_str[0] == '"' or name_str[0] == '\''))
                name_str[1 .. name_str.len - 1]
            else
                name_str;
            return self.getTypeOfPropertyOfType(ctx_type, cleaned_name);
        }
        return 0;
    }

    /// Port of `checker.go::getContextualTypeForArgumentAtIndex`.
    /// Returns the contextual type for the argument at `argIndex` in the
    /// call expression `node`. Resolves the call signature and returns
    /// the parameter type at the given index. Handles rest parameters
    /// by returning the rest array's element type for out-of-bounds indices.
    pub fn getContextualTypeForArgumentAtIndex(self: *Checker, node: ast_gen.NodeIndex, argIndex: usize) types.TypeIndex {
        if (node == 0) return 0;
        const node_kind = self.binder.ast.getKind(node);
        // ImportCall: argument 0 is string, argument 1 is options.
        if (node_kind == .ImportCall) {
            return switch (argIndex) {
                0 => self.stringTypeIndex orelse 0,
                1 => 0, // getGlobalImportCallOptionsType - stub
                else => self.anyTypeIndex orelse 0,
            };
        }
        // Resolve the call signature.
        const signature = self.getResolvedSignature(node, null, .Normal);
        if (signature == 0 or signature >= self.signatures.items.len) return 0;
        const sig = &self.signatures.items[signature];
        const params = types.parameters(self, signature);
        const has_rest = (sig.flags & types.SignatureFlags.HasRestParameter) != 0;
        const param_count: usize = if (has_rest and params.len > 0) params.len - 1 else params.len;
        if (argIndex < param_count) {
            return self.getTypeOfParameter(params[argIndex]);
        }
        if (has_rest and params.len > 0) {
            // Out-of-bounds with rest parameter — return rest element type.
            const rest_symbol = params[param_count];
            const rest_type = self.getTypeOfSymbol(rest_symbol) catch return 0;
            return self.getElementTypeOfArrayType(rest_type);
        }
        return 0;
    }

    pub fn getContextualType(c: *Checker, node: ast_gen.NodeIndex, contextFlags: u32) types.TypeIndex {
        // Go: complex — switch on parent.Kind, delegating to many getContextualTypeFor* helpers.
        // Simplified: handle common cases (VariableDeclaration, Parameter, PropertyDeclaration,
        // ParenthesizedExpression, NonNullExpression) directly, return 0 for others.
        const parent = c.binder.ast.getNodeParent(node);
        if (parent == 0) return 0;
        const pk = c.binder.ast.getKind(parent);
        switch (pk) {
            .VariableDeclaration, .Parameter, .PropertyDeclaration, .PropertySignature, .BindingElement => {
                // Get type annotation from declaration
                const type_node: ?ast_gen.NodeIndex = switch (c.binder.ast.getNode(parent)) {
                    .VariableDeclaration => |n| n.Type,
                    .Parameter => |n| n.Type,
                    .PropertyDeclaration => |n| n.Type,
                    .PropertySignature => |n| n.Type,
                    .BindingElement => null,
                    else => null,
                };
                if (type_node) |tn| {
                    if (tn != 0) return c.getTypeFromTypeNode(tn);
                }
                return 0;
            },
            .ParenthesizedExpression, .NonNullExpression => {
                return c.getContextualType(parent, contextFlags);
            },
            .TypeAssertionExpression, .AsExpression => {
                const type_node = c.binder.ast.getNode(parent).TypeAssertionExpression.Type;
                if (type_node != 0) return c.getTypeFromTypeNode(type_node);
                return 0;
            },
            else => return 0,
        }
    }

    /// Get the contextual type for a parameter of a function expression that's
    /// passed as an argument to a call. `param_node` is the Parameter node,
    /// `fn_node` is the function-like parent (FunctionExpression, ArrowFunction).
    /// Returns the parameter type from the contextual signature, or 0 if none.
    pub fn getContextualParameterType(c: *Checker, param_node: ast_gen.NodeIndex, fn_node: ast_gen.NodeIndex) ?types.TypeIndex {
        // Find the parameter index in fn_node's parameter list.
        const fn_data = c.binder.ast.getNode(fn_node);
        const params_id: u32 = switch (fn_data) {
            .FunctionExpression => |f| f.Parameters,
            .ArrowFunction => |f| f.Parameters,
            .FunctionDeclaration => |f| f.Parameters,
            .MethodDeclaration => |m| m.Parameters,
            else => return null,
        };
        if (params_id == 0) return null;
        const params = c.binder.ast.getNodeList(params_id);
        var param_idx: ?usize = null;
        var skipped_this = false;
        for (params, 0..) |p, i| {
            if (p == param_node) {
                // Adjust index: skip `this` parameter (first param named "this").
                var adj_idx = i;
                if (!skipped_this and params.len > 0) {
                    const first_param = params[0];
                    if (first_param != 0) {
                        const first_param_data = c.binder.ast.getNode(first_param);
                        if (first_param_data == .Parameter) {
                            const fp_name_node = first_param_data.Parameter.name;
                            if (fp_name_node != 0) {
                                const fp_name = ast_utils.getTextOfNode(c.binder.ast, fp_name_node);
                                if (std.mem.eql(u8, fp_name, "this")) {
                                    if (p != first_param) adj_idx = i - 1;
                                    skipped_this = true;
                                }
                            }
                        }
                    }
                }
                param_idx = adj_idx;
                break;
            }
        }
        if (param_idx == null) return null;
        const idx = param_idx.?;

        // Walk up from fn_node to find a CallExpression that has fn_node as an argument.
        var cur = c.binder.ast.getNodeParent(fn_node);
        // Walk through ParenthesizedExpression/NonNullExpression which are transparent.
        while (cur != 0) {
            const k = c.binder.ast.getNodeKind(cur);
            if (k == .ParenthesizedExpression or k == .NonNullExpression) {
                cur = c.binder.ast.getNodeParent(cur);
                continue;
            }
            break;
        }
        while (cur != 0) {
            const k = c.binder.ast.getNodeKind(cur);
            if (k == .CallExpression or k == .NewExpression) {
                const args_id_opt: ?u32 = if (k == .CallExpression) c.binder.ast.getNode(cur).CallExpression.Arguments else c.binder.ast.getNode(cur).NewExpression.Arguments;
                if (args_id_opt == null or args_id_opt.? == 0) return null;
                const args = c.binder.ast.getNodeList(args_id_opt.?);
                var arg_idx: ?usize = null;
                for (args, 0..) |a, i| {
                    if (a == fn_node) {
                        arg_idx = i;
                        break;
                    }
                }
                if (arg_idx == null) return null;
                const a_idx = arg_idx.?;

                // Get the resolved signature and look up the parameter type.
                const sig = c.getResolvedSignature(cur, null, .Normal);
                if (sig == 0 or sig >= c.signatures.items.len) return null;
                const sig_obj = &c.signatures.items[sig];
                if (a_idx >= sig_obj.parametersLen) return null;
                if (sig_obj.parametersStart + a_idx >= c.signatureParameters.items.len) return null;
                const param_sym = c.signatureParameters.items[sig_obj.parametersStart + a_idx];
                if (param_sym == 0 or param_sym >= c.binder.symbols.items.len) return null;

                // First, try to get the parameter's type annotation directly
                // from its declaration node. This handles FunctionType annotations
                // that aren't fully resolved.
                if (param_sym < c.binder.symbols.items.len) {
                    const param_sym_obj = c.binder.symbols.items[param_sym];
                    if (param_sym_obj.Declarations.items.len > 0) {
                        const param_decl = param_sym_obj.Declarations.items[0];
                        if (param_decl != 0 and c.binder.ast.getNodeKind(param_decl) == .Parameter) {
                            const param_data = c.binder.ast.getNode(param_decl).Parameter;
                            if (param_data.Type) |param_type_node| {
                                if (param_type_node != 0) {
                                    const param_type_kind = c.binder.ast.getNodeKind(param_type_node);
                                    // If the parameter type is a FunctionType, extract
                                    // the inner parameter type directly.
                                    if (param_type_kind == .FunctionType or param_type_kind == .ConstructorType) {
                                        const ft_params_id: u32 = if (param_type_kind == .FunctionType) c.binder.ast.getNode(param_type_node).FunctionType.Parameters else c.binder.ast.getNode(param_type_node).ConstructorType.Parameters;
                                        if (ft_params_id != 0) {
                                            const ft_params = c.binder.ast.getNodeList(ft_params_id);
                                            if (idx < ft_params.len) {
                                                const ft_param = ft_params[idx];
                                                if (ft_param != 0) {
                                                    const ft_param_data = c.binder.ast.getNode(ft_param).Parameter;
                                                    if (ft_param_data.Type) |pt| {
                                                        if (pt != 0) {
                                                            const inner_type = type_resolution_pkg.getTypeFromTypeNode(c, pt);
                                                            if (inner_type != 0) return inner_type;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                const outer_param_type = c.getTypeOfSymbol(param_sym) catch 0;
                if (outer_param_type == 0) return null;

                // The outer parameter type is the contextual type for the
                // function expression. If it's a function type, extract the
                // corresponding parameter type from its signature.
                const inner_sigs = c.getSignaturesOfType(outer_param_type, .Call);
                if (inner_sigs.len == 0) return null;
                const inner_sig_idx = c.resolvedSignaturesPool.items[inner_sigs.start];
                if (inner_sig_idx >= c.signatures.items.len) return null;
                const inner_sig = &c.signatures.items[inner_sig_idx];
                if (idx >= inner_sig.parametersLen) return null;
                if (inner_sig.parametersStart + idx >= c.signatureParameters.items.len) return null;
                const inner_param_sym = c.signatureParameters.items[inner_sig.parametersStart + idx];
                if (inner_param_sym == 0 or inner_param_sym >= c.binder.symbols.items.len) return null;
                const inner_param_type = c.getTypeOfSymbol(inner_param_sym) catch 0;
                if (inner_param_type != 0) return inner_param_type;
                return null;
            }
            // VariableDeclaration with type annotation: the contextual type
            // is the variable's type annotation.
            if (k == .VariableDeclaration) {
                const vd = c.binder.ast.getNode(cur).VariableDeclaration;
                if (vd.Type) |type_node| {
                    if (type_node != 0) {
                        // For FunctionType nodes, directly extract the parameter type.
                        const type_node_kind = c.binder.ast.getNodeKind(type_node);
                        if (type_node_kind == .FunctionType or type_node_kind == .ConstructorType) {
                            const ft_params_id: u32 = if (type_node_kind == .FunctionType) c.binder.ast.getNode(type_node).FunctionType.Parameters else c.binder.ast.getNode(type_node).ConstructorType.Parameters;
                            if (ft_params_id != 0) {
                                const ft_params = c.binder.ast.getNodeList(ft_params_id);
                                if (idx < ft_params.len) {
                                    const ft_param = ft_params[idx];
                                    if (ft_param != 0) {
                                        const ft_param_data = c.binder.ast.getNode(ft_param).Parameter;
                                        if (ft_param_data.Type) |pt| {
                                            if (pt != 0) return c.getTypeFromTypeNode(pt);
                                        }
                                    }
                                }
                            }
                        }
                        const ctx_type = c.getTypeFromTypeNode(type_node);
                        if (ctx_type != 0) {
                            const inner_sigs = c.getSignaturesOfType(ctx_type, .Call);
                            if (inner_sigs.len > 0) {
                                const inner_sig_idx = c.resolvedSignaturesPool.items[inner_sigs.start];
                                if (inner_sig_idx < c.signatures.items.len) {
                                    const inner_sig = &c.signatures.items[inner_sig_idx];
                                    if (idx < inner_sig.parametersLen and
                                        inner_sig.parametersStart + idx < c.signatureParameters.items.len)
                                    {
                                        const inner_param_sym = c.signatureParameters.items[inner_sig.parametersStart + idx];
                                        if (inner_param_sym != 0 and inner_param_sym < c.binder.symbols.items.len) {
                                            const inner_param_type = c.getTypeOfSymbol(inner_param_sym) catch 0;
                                            if (inner_param_type != 0) return inner_param_type;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return null;
            }
            // PropertyDeclaration/PropertySignature with type annotation:
            // the contextual type is the property's type annotation.
            // E.g. `foo: (i: number, s: string) => number = function(i) { ... }`
            if (k == .PropertyDeclaration or k == .PropertySignature or k == .PropertyAssignment) {
                const type_node: ?ast_gen.NodeIndex = switch (c.binder.ast.getNode(cur)) {
                    .PropertyDeclaration => |n| n.Type,
                    .PropertySignature => |n| n.Type,
                    .PropertyAssignment => |n| n.Type,
                    else => null,
                };
                if (type_node) |tn| {
                    if (tn != 0) {
                        // For FunctionType nodes, directly extract the parameter type.
                        const type_node_kind = c.binder.ast.getNodeKind(tn);
                        if (type_node_kind == .FunctionType or type_node_kind == .ConstructorType) {
                            const ft_params_id: u32 = if (type_node_kind == .FunctionType) c.binder.ast.getNode(tn).FunctionType.Parameters else c.binder.ast.getNode(tn).ConstructorType.Parameters;
                            if (ft_params_id != 0) {
                                const ft_params = c.binder.ast.getNodeList(ft_params_id);
                                if (idx < ft_params.len) {
                                    const ft_param = ft_params[idx];
                                    if (ft_param != 0) {
                                        const ft_param_data = c.binder.ast.getNode(ft_param).Parameter;
                                        if (ft_param_data.Type) |pt| {
                                            if (pt != 0) return c.getTypeFromTypeNode(pt);
                                        }
                                    }
                                }
                            }
                        }
                        const ctx_type = c.getTypeFromTypeNode(tn);
                        if (ctx_type != 0) {
                            const inner_sigs = c.getSignaturesOfType(ctx_type, .Call);
                            if (inner_sigs.len > 0) {
                                const inner_sig_idx = c.resolvedSignaturesPool.items[inner_sigs.start];
                                if (inner_sig_idx < c.signatures.items.len) {
                                    const inner_sig = &c.signatures.items[inner_sig_idx];
                                    if (idx < inner_sig.parametersLen and
                                        inner_sig.parametersStart + idx < c.signatureParameters.items.len)
                                    {
                                        const inner_param_sym = c.signatureParameters.items[inner_sig.parametersStart + idx];
                                        if (inner_param_sym != 0 and inner_param_sym < c.binder.symbols.items.len) {
                                            const inner_param_type = c.getTypeOfSymbol(inner_param_sym) catch 0;
                                            if (inner_param_type != 0) return inner_param_type;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return null;
            }
            if (k == .SourceFile or k == .Block or k == .FunctionDeclaration or k == .FunctionExpression or k == .ArrowFunction or k == .MethodDeclaration) return null;
            cur = c.binder.ast.getNodeParent(cur);
        }
        return null;
    }


    pub fn isFunctionType(c: *Checker, t: types.TypeIndex) bool {
        return (c.getTypeFlags(t) & types.TypeFlags.Object) != 0 and c.getSignaturesOfType(t, .Call).len > 0;
    }

    pub fn isConstructorType(c: *Checker, t: types.TypeIndex) bool {
        if (c.getSignaturesOfType(t, .Construct).len > 0) {
            return true;
        }
        if ((c.getTypeFlags(t) & types.TypeFlags.TypeVariable) != 0) {
            const constraint = c.getBaseConstraintOfType(t);
            return constraint != 0 and c.isMixinConstructorType(constraint);
        }
        return false;
    }

    pub fn getElementTypeOfArrayType(c: *Checker, t: types.TypeIndex) types.TypeIndex {
        if (c.isArrayType(t)) {
            if (c.typesList.items[t].data == .Array) {
                return c.typesList.items[t].data.Array.elementType;
            }
            // Reference type — get target's element type, then substitute
            // type parameters with the reference's type arguments.
            const target = c.getTargetType(t);
            if (target != 0 and target < c.typesList.items.len and c.typesList.items[target].data == .Array) {
                const elem_type = c.typesList.items[target].data.Array.elementType;
                // If the reference has type arguments, substitute.
                if ((c.typesList.items[t].objectFlags & types.ObjectFlags.Reference) != 0) {
                    const ta = c.getTypeArguments(t);
                    if (ta.len > 0) {
                        // Build substitution map from target's type parameter symbols
                        // to the reference's type arguments.
                        const target_sym = c.getSymbolOfType(target);
                        if (target_sym != 0 and target_sym < c.binder.symbols.items.len) {
                            const sym_obj = c.binder.symbols.items[target_sym];
                            if (sym_obj.Declarations.items.len > 0) {
                                const decl = sym_obj.Declarations.items[0];
                                const decl_data = c.binder.ast.getNode(decl);
                                const tp_list: ?u32 = switch (decl_data) {
                                    .InterfaceDeclaration => |id| id.TypeParameters,
                                    .ClassDeclaration => |cd| cd.TypeParameters,
                                    else => null,
                                };
                                if (tp_list) |tpl| {
                                    if (tpl != 0) {
                                        const tp_nodes = c.binder.ast.getNodeList(tpl);
                                        if (tp_nodes.len == ta.len) {
                                            var subst = std.AutoHashMap(ast_gen.SymbolIndex, types.TypeIndex).init(c.allocator);
                                            defer subst.deinit();
                                            for (tp_nodes, 0..) |tp_node, i| {
                                                if (tp_node != 0) {
                                                    const tp_sym = c.binder.ast.getNodeSymbol(tp_node) orelse 0;
                                                    if (tp_sym != 0) {
                                                        subst.put(tp_sym, ta[i]) catch {};
                                                    }
                                                }
                                            }
                                            return c.substituteTypeParams(elem_type, &subst) catch elem_type;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return elem_type;
            }
            // Not directly Array — check base types (e.g., interface Foo<T> extends Array<T>).
            if ((c.typesList.items[t].objectFlags & types.ObjectFlags.Reference) != 0) {
                if (target != 0 and target < c.typesList.items.len and
                    (c.typesList.items[target].objectFlags & types.ObjectFlags.ClassOrInterface) != 0)
                {
                    for (c.getBaseTypes(target)) |bt| {
                        if (c.isArrayType(bt)) {
                            // Found Array base type. Get its element type, then
                            // substitute the target's type parameters with the
                            // reference's type arguments.
                            const elem_type = c.getElementTypeOfArrayType(bt);
                            if (elem_type != 0) {
                                const ta = c.getTypeArguments(t);
                                if (ta.len > 0) {
                                    const target_sym = c.getSymbolOfType(target);
                                    if (target_sym != 0 and target_sym < c.binder.symbols.items.len) {
                                        const sym_obj = c.binder.symbols.items[target_sym];
                                        if (sym_obj.Declarations.items.len > 0) {
                                            const decl = sym_obj.Declarations.items[0];
                                            const decl_data = c.binder.ast.getNode(decl);
                                            const tp_list: ?u32 = switch (decl_data) {
                                                .InterfaceDeclaration => |id| id.TypeParameters,
                                                .ClassDeclaration => |cd| cd.TypeParameters,
                                                else => null,
                                            };
                                            if (tp_list) |tpl| {
                                                if (tpl != 0) {
                                                    const tp_nodes = c.binder.ast.getNodeList(tpl);
                                                    if (tp_nodes.len == ta.len) {
                                                        var subst = std.AutoHashMap(ast_gen.SymbolIndex, types.TypeIndex).init(c.allocator);
                                                        defer subst.deinit();
                                                        for (tp_nodes, 0..) |tp_node, i| {
                                                            if (tp_node != 0) {
                                                                const tp_sym = c.binder.ast.getNodeSymbol(tp_node) orelse 0;
                                                                if (tp_sym != 0) {
                                                                    subst.put(tp_sym, ta[i]) catch {};
                                                                }
                                                            }
                                                        }
                                                        return c.substituteTypeParams(elem_type, &subst) catch elem_type;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                return elem_type;
                            }
                        }
                    }
                }
            }
            // Direct ClassOrInterface — check base types.
            if ((c.typesList.items[t].objectFlags & types.ObjectFlags.ClassOrInterface) != 0) {
                for (c.getBaseTypes(t)) |bt| {
                    if (c.isArrayType(bt)) {
                        return c.getElementTypeOfArrayType(bt);
                    }
                }
            }
        }
        return 0;
    }

    pub fn signatureHasRestParameter(sig: *const types.Signature) bool {
        return (sig.flags & types.SignatureFlags.HasRestParameter) != 0;
    }

    pub fn addOptionalityEx(c: *Checker, t: types.TypeIndex, isProperty: bool, isOptional: bool) types.TypeIndex {
        if (isOptional) {
            return c.getOptionalType(t, isProperty);
        }
        return t;
    }

    pub fn getTypeOfParameter(c: *Checker, sym: ast_gen.SymbolIndex) types.TypeIndex {
        const declaration = c.getSymbolValueDeclaration(sym);
        var isOptional = false;
        if (declaration != 0) {
            isOptional = utils.isOptionalDeclaration(c.binder.ast, declaration) or ast_utils.getInitializerOfNode(c.binder.ast, declaration) != 0;
        }
        const t = c.getTypeOfSymbol(sym) catch (c.unknownTypeIndex orelse 0);
        return c.addOptionalityEx(t, false, isOptional);
    }

    pub fn isMixinConstructorType(c: *Checker, t: types.TypeIndex) bool {
        const signatures = c.getSignaturesOfType(t, .Construct);
        if (signatures.len == 1) {
            const sigIndex = c.resolvedSignaturesPool.items[signatures.start];
            const s = c.signatures.items[sigIndex];
            if (s.typeParametersLen == 0 and s.parametersLen == 1 and signatureHasRestParameter(&s)) {
                const paramSymbol = c.signatureParameters.items[s.parametersStart];
                const paramType = c.getTypeOfParameter(paramSymbol);
                if ((c.getTypeFlags(paramType) & types.TypeFlags.Any) != 0 or c.getElementTypeOfArrayType(paramType) == (c.anyTypeIndex orelse 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    pub fn createArrayType(c: *Checker, elementType: types.TypeIndex) types.TypeIndex {
        return c.createType(.{
            .flags = types.TypeFlags.Object,
            .objectFlags = types.ObjectFlags.Reference,
            .id = 0,
            .symbol = null,
            .alias = null,
            .data = .{ .Array = .{ .elementType = elementType } },
        }) catch 0;
    }

    pub fn someType(c: *Checker, t: types.TypeIndex, comptime predicate: anytype, ctx: anytype) bool {
        const flags = c.getTypeFlags(t);
        if ((flags & types.TypeFlags.Union) != 0) {
            const unionTypes = c.getTypesFromUnion(t);
            for (unionTypes) |u| {
                if (predicate(c, u, ctx)) {
                    return true;
                }
            }
            return false;
        }
        return predicate(c, t, ctx);
    }

    pub fn everyType(c: *Checker, t: types.TypeIndex, comptime predicate: anytype, ctx: anytype) bool {
        const flags = c.getTypeFlags(t);
        if ((flags & types.TypeFlags.Union) != 0) {
            const unionTypes = c.getTypesFromUnion(t);
            for (unionTypes) |u| {
                if (!predicate(c, u, ctx)) {
                    return false;
                }
            }
            return true;
        }
        return predicate(c, t, ctx);
    }
