    /// creates two `IterationTypesResolver` structs (sync and async) that
    /// cache function references for resolving iterator types (Iterator,
    /// Iterable, Generator, etc.). In Zig, iteration type resolution is
    /// handled directly by `getIteratedTypeOrElementType` and related
    /// methods, so this function is a no-op for API parity.
    pub fn initializeIterationResolvers(c: *Checker) void {        _ = c;
        // No-op: full implementation not yet wired.
    }

    /// Port of checker.go::initializeChecker. Initializes the global symbol
    /// table by merging global symbols from all source files. Simplified:
    /// iterates source file locals and merges non-module symbols into
    /// the global symbol table.
    pub fn initializeChecker(c: *Checker) void {
        // Initialize closures and iteration resolvers.
        c.initializeClosures();
        c.initializeIterationResolvers();
        // Eagerly initialize common intrinsic type indices so that callers
        // can use `c.voidTypeIndex orelse 0` without worrying about lazy init.
        _ = c.getVoidType() catch {};
        _ = c.getAnyType() catch {};
        _ = c.getStringType() catch {};
        _ = c.getNumberType() catch {};
        _ = c.getBooleanType() catch {};
        _ = c.getUndefinedType() catch {};
        _ = c.getNullType() catch {};
        _ = c.getUnknownType() catch {};
        _ = c.getNeverType() catch {};
        // Initialize esSymbolType if not already set.
        if (c.esSymbolTypeIndex == null) {
            const idx = c.createType(.{
                .flags = types.TypeFlags.ESSymbol,
                .objectFlags = types.ObjectFlags.Anonymous,
                .id = 0,
                .symbol = null,
                .alias = null,
                .data = .{ .Intrinsic = .{ .intrinsicName = "symbol" } },
            }) catch 0;
            c.esSymbolTypeIndex = idx;
        }
        // Initialize stringNumberSymbolType = string | number | symbol.
        if (c.stringNumberSymbolType == 0) {
            const str_type = c.getStringType() catch 0;
            const num_type = c.getNumberType() catch 0;
            const sym_type = c.esSymbolTypeIndex orelse 0;
            if (str_type != 0 and num_type != 0 and sym_type != 0) {
                const types_arr = [_]types.TypeIndex{ str_type, num_type, sym_type };
                c.stringNumberSymbolType = c.getUnionTypeFromArray(&types_arr);
            }
        }
        // Create a synthetic RegExp symbol for when lib.d.ts is not loaded.
        if (c.regExpSymbolIndex == null) {
            const sym_idx: ast_gen.SymbolIndex = @intCast(c.binder.symbols.items.len);
            c.binder.symbols.append(c.binder.allocator, .{
                .Flags = symbol.SymbolFlags.Class,
                .Name = "RegExp",
                .Declarations = std.ArrayListUnmanaged(ast_gen.NodeIndex).empty,
                .ValueDeclaration = null,
                .Members = symbol.SymbolTable.empty,
                .Exports = symbol.SymbolTable.empty,
                .Parent = null,
                .ExportSymbol = null,
            }) catch {};
            c.regExpSymbolIndex = sym_idx;
        }
        // Create a synthetic Array interface symbol for when lib.d.ts is not loaded.
        // This allows `interface Foo<T> extends Array<T>` to resolve.
        if (c.arraySymbolIndex == null) {
            const sym_idx: ast_gen.SymbolIndex = @intCast(c.binder.symbols.items.len);
            c.binder.symbols.append(c.binder.allocator, .{
                .Flags = symbol.SymbolFlags.Interface,
                .Name = "Array",
                .Declarations = std.ArrayListUnmanaged(ast_gen.NodeIndex).empty,
                .ValueDeclaration = null,
                .Members = symbol.SymbolTable.empty,
                .Exports = symbol.SymbolTable.empty,
                .Parent = null,
                .ExportSymbol = null,
            }) catch {};
            c.arraySymbolIndex = sym_idx;
        }
        // Build the global symbol table by merging SourceFile locals
        // (like Go's initializeChecker which merges globals).
        c.globalsSymbolTable = .{};
        // Walk all SourceFile node locals and merge type symbols into globals.
        var locals_it = c.binder.nodeLocals.iterator();
        while (locals_it.next()) |entry| {
            const node_idx = entry.key_ptr.*;
            const locals = entry.value_ptr.*;
            // Only process SourceFile nodes.
            if (c.binder.ast.getNodeKind(node_idx) == .SourceFile) {
                var sym_it = locals.iterator();
                while (sym_it.next()) |sym_entry| {
                    const sym_name = sym_entry.key_ptr.*;
                    const sym_idx = sym_entry.value_ptr.*;
                    if (sym_idx != 0 and sym_idx < c.binder.symbols.items.len) {
                        const sym_flags = c.binder.symbols.items[sym_idx].Flags;
                        // Only merge type and value symbols (not locals).
                        if ((sym_flags & (symbol.SymbolFlags.Type | symbol.SymbolFlags.Value | symbol.SymbolFlags.Namespace)) != 0) {
                            c.globalsSymbolTable.put(c.binder.allocator, sym_name, sym_idx) catch {};
                        }
                    }
                }
            }
        }
        // Set Globals on the resolver so resolveName can find global symbols.
        c.resolver.Globals = &c.globalsSymbolTable;
        // Register synthetic Array symbol in globals.
        if (c.arraySymbolIndex) |arr_sym| {
            if (!c.globalsSymbolTable.contains("Array")) {
                c.globalsSymbolTable.put(c.binder.allocator, "Array", arr_sym) catch {};
            }
        }
    }

