    pub fn getPrimitiveTypeAliasSuggestions(c: *Checker, symbols: *symbol.SymbolTable) ?ast_gen.SymbolIndex {
        // Go: for builtinName, suggestion := range primitiveTypeAliasSuggestions() {
        //   if _, ok := symbols[builtinName]; ok { yield suggestion }
        // }
        // Simplified port: yields the first matching primitive alias suggestion.
        // The mapping is builtin -> primitive name.
        const pairs = [_]struct { builtin: []const u8, primitive: []const u8 }{
            .{ .builtin = "String", .primitive = "string" },
            .{ .builtin = "Number", .primitive = "number" },
            .{ .builtin = "Boolean", .primitive = "boolean" },
            .{ .builtin = "Object", .primitive = "object" },
            .{ .builtin = "BigInt", .primitive = "bigint" },
            .{ .builtin = "Symbol", .primitive = "symbol" },
        };
        for (pairs) |p| {
            if (symbols.get(p.builtin)) |sym_idx| {
                _ = c;
                return sym_idx;
            }
        }
        return null;
    }

    /// Port of `checker.go::getSuggestionForSymbolNameLookup`. Returns a
    /// suggested symbol by first looking up `name_` directly in `symbols`
    /// with the given meaning, then falling back to spelling suggestion.
    pub fn getSuggestionForSymbolNameLookup(c: *Checker, symbols: *const symbol.SymbolTable, name_: []const u8, meaning: u32) ast_gen.SymbolIndex {
        // Direct lookup.
        if (symbols.get(name_)) |sym| {
            const flags = c.getSymbolFlags(sym);
            if ((flags & meaning) != 0) return sym;
        }
        // Fall back to spelling suggestion.
        var it = symbols.iterator();
        var best: ast_gen.SymbolIndex = 0;
        var best_distance: usize = std.math.maxInt(usize);
        while (it.next()) |entry| {
            const candidate_name = entry.key_ptr.*;
            const sym = entry.value_ptr.*;
            const flags = c.getSymbolFlags(sym);
            if ((flags & meaning) == 0) continue;
            // Simple Levenshtein-like check: case-insensitive equality or
            // length-difference threshold.
            if (std.ascii.eqlIgnoreCase(candidate_name, name_)) return sym;
            if (candidate_name.len > 0 and name_.len > 0) {
                const dist = levenshteinDistance(name_, candidate_name);
                if (dist < best_distance) {
                    best_distance = dist;
                    best = sym;
                }
            }
        }
        // Only return if distance is reasonable (≤ 2).
        if (best != 0 and best_distance <= 2) return best;
        return 0;
    }

    /// Port of `checker.go::getSpellingSuggestionForName`. Returns the
    /// closest matching symbol by Levenshtein distance from `symbols`.
    pub fn getSpellingSuggestionForName(c: *Checker, name_: []const u8, symbols: *const symbol.SymbolTable, meaning: u32) ast_gen.SymbolIndex {
        var it = symbols.iterator();
        var best: ast_gen.SymbolIndex = 0;
        var best_distance: usize = std.math.maxInt(usize);
        while (it.next()) |entry| {
            const candidate_name = entry.key_ptr.*;
            const sym = entry.value_ptr.*;
            const flags = c.getSymbolFlags(sym);
            if ((flags & meaning) == 0) continue;
            if (candidate_name.len == 0) continue;
            if (std.ascii.eqlIgnoreCase(candidate_name, name_)) return sym;
            const dist = levenshteinDistance(name_, candidate_name);
            if (dist < best_distance) {
                best_distance = dist;
                best = sym;
            }
        }
        if (best != 0 and best_distance <= 2) return best;
        return 0;
    }

    /// Port of `checker.go::onSuccessfullyResolvedSymbol`. Performs post-
    /// resolution checks: block-scoped variable checks, UMD global access
    /// checks, and parameter initializer scope checks.
    pub fn onSuccessfullyResolvedSymbol(c: *Checker, errorLocation: ast_gen.NodeIndex, result: ast_gen.SymbolIndex, meaning: u32, lastLocation: ast_gen.NodeIndex, associatedDeclarationForContainingInitializerOrBindingName: ast_gen.NodeIndex, withinDeferredContext: bool) void {
        _ = associatedDeclarationForContainingInitializerOrBindingName;
        _ = withinDeferredContext;
        if (result == 0 or result >= c.binder.symbols.items.len) return;
        const sym = c.binder.symbols.items[result];
        const name = sym.Name;
        // Check for block-scoped variable usage.
        if (errorLocation != 0 and
            ((meaning & symbol.SymbolFlags.BlockScopedVariable) != 0 or
             ((meaning & (symbol.SymbolFlags.Class | symbol.SymbolFlags.Enum)) != 0 and
              (meaning & symbol.SymbolFlags.Value) == symbol.SymbolFlags.Value)))
        {
            const export_or_local = c.getExportSymbolOfValueSymbolIfExported(result);
            if (export_or_local < c.binder.symbols.items.len) {
                const flags = c.binder.symbols.items[export_or_local].Flags;
                if ((flags & (symbol.SymbolFlags.BlockScopedVariable | symbol.SymbolFlags.Class | symbol.SymbolFlags.Enum)) != 0) {
                    c.checkResolvedBlockScopedVariable(export_or_local, errorLocation);
                }
            }
        }
        // Check for UMD global access in external modules.
        const is_external_module = lastLocation != 0 and
            c.binder.ast.getKind(lastLocation) == .SourceFile;
        if (is_external_module and (meaning & symbol.SymbolFlags.Value) == symbol.SymbolFlags.Value) {
            const merged = getMergedSymbol(c, result);
            if (merged < c.binder.symbols.items.len) {
                const merged_sym = c.binder.symbols.items[merged];
                if (merged_sym.Declarations.items.len > 0) {
                    // Check if all declarations are namespace export or source file with global exports.
                    var all_global = true;
                    for (merged_sym.Declarations.items) |d| {
                        const k = c.binder.ast.getKind(d);
                        if (k != .NamespaceExportDeclaration and k != .SourceFile) {
                            all_global = false;
                            break;
                        }
                    }
                    if (all_global) {
                        c.reportErrorWithArgs(errorLocation, &diagnostics_gen.X_0_refers_to_a_UMD_global_but_the_current_file_is_a_module_Consider_adding_an_import_instead, &.{name});
                    }
                }
            }
        }
    }

    /// Simple Levenshtein distance between two strings. Used by spelling
    /// suggestion functions. Returns the edit distance (insertions +
    /// deletions + substitutions).
    fn levenshteinDistance(s1: []const u8, s2: []const u8) usize {
        if (s1.len == 0) return s2.len;
        if (s2.len == 0) return s1.len;
        // Use a single rolling row of size s2.len+1.
        var row: [256]usize = undefined;
        if (s2.len + 1 > row.len) return std.math.maxInt(usize); // bail out for very long names
        for (row[0 .. s2.len + 1], 0..) |*v, i| v.* = i;
        var prev: usize = 0;
        for (s1, 0..) |c1, i| {
            prev = i + 1;
            const val = row[0];
            row[0] = prev;
            _ = val;
            for (s2, 0..) |c2, j| {
                const cost: usize = if (c1 == c2) 0 else 1;
                const old = row[j + 1];
                const new_dist = @min(@min(row[j] + 1, row[j + 1] + 1), prev + cost);
                row[j + 1] = new_dist;
                prev = old;
            }
        }
        return row[s2.len];
    }

    /// Port of `checker.go::checkResolvedBlockScopedVariable`. Validates
    /// that a block-scoped variable, class, or enum is not used before its
    /// declaration. Reports a `Block_scoped_variable_0_used_before_its_declaration`,
    /// `Class_0_used_before_its_declaration`, or
    /// `Enum_0_used_before_its_declaration` error if the use precedes the
    /// declaration.
    pub fn checkResolvedBlockScopedVariable(c: *Checker, result: ast_gen.NodeIndex, error_location: ast_gen.NodeIndex) void {
        // Note: Go signature is (result *ast.Symbol, errorLocation *ast.Node).
        // The Zig signature incorrectly takes `result` as a NodeIndex;
        // for now we treat it as the symbol's value declaration node.
        if (result == 0) return;
        // Walk up to find the block-scoped declaration. For VariableDeclaration,
        // the declaration is `result` itself; for class/enum, same.
        const declaration = result;
        // Check if the declaration is marked ambient — ambient declarations
        // are hoisted and can be used before their textual position.
        const node_flags = c.binder.ast.getNodeFlags(declaration);
        if ((node_flags & ast_utils.NodeFlags.Ambient) != 0) return;
        if (!c.isBlockScopedNameDeclaredBeforeUse(declaration, error_location)) {
            // Get the declaration name for the error message.
            const name_node = ast_utils.getPropertyNameOfNode(c.binder.ast, declaration);
            const name_str = if (name_node != 0) ast_utils.getTextOfNode(c.binder.ast, name_node) else "<anonymous>";
            c.reportErrorWithArgs(error_location, &diagnostics_gen.Block_scoped_variable_0_used_before_its_declaration, &.{name_str});
        }
    }

    /// Port of `checker.go::isBlockScopedNameDeclaredBeforeUse`. Returns
    /// true if `declaration` is textually positioned before `usage` in the
    /// same source file, or if the usage is deferred (inside a function
    /// body or instance property initializer). Returns false if the usage
    /// precedes the declaration and is not deferred.
    pub fn isBlockScopedNameDeclaredBeforeUse(c: *Checker, declaration: ast_gen.NodeIndex, usage: ast_gen.NodeIndex) bool {
        if (declaration == 0 or usage == 0) return true;
        // Get source positions.
        const decl_pos = c.binder.ast.getNodePos(declaration);
        const usage_pos = c.binder.ast.getNodePos(usage);
        // If declaration is before usage, it's declared before use — unless
        // the usage is in the initializer of the declaration itself
        // (e.g., `var a = a`).
        if (decl_pos <= usage_pos) {
            // For VariableDeclaration, check if usage is in the initializer.
            const decl_kind = c.binder.ast.getKind(declaration);
            if (decl_kind == .VariableDeclaration) {
                // If usage is in the initializer of `declaration`, it's illegal.
                // We check this by walking up from `usage` to see if we hit
                // `declaration` before crossing a function boundary.
                if (c.isImmediatelyUsedInInitializerOfBlockScopedVariable(declaration, usage, 0)) {
                    return false;
                }
            }
            return true;
        }
        // Declaration is after usage — check if usage is deferred.
        // 1. Inside an export specifier: deferred.
        const usage_parent = c.binder.ast.getNodeParent(usage);
        if (usage_parent != 0) {
            const parent_kind = c.binder.ast.getKind(usage_parent);
            if (parent_kind == .ExportSpecifier) return true;
            if (parent_kind == .ExportAssignment) return true;
        }
        // 2. Inside a function body or instance property initializer: deferred.
        if (c.isUsedInFunctionOrInstanceProperty(usage, declaration, 0)) return true;
        return false;
    }

    /// Port of `checker.go::isUsedInFunctionOrInstanceProperty`. Returns
    /// true if `usage` is inside a function body, an instance property
    /// initializer, a static block, or a decorator — contexts where the
    /// use is deferred until runtime, so a textual-before-declaration
    /// use is legal. Returns false otherwise.
    pub fn isUsedInFunctionOrInstanceProperty(c: *Checker, usage: ast_gen.NodeIndex, declaration: ast_gen.NodeIndex, declContainer: ast_gen.NodeIndex) bool {
        if (usage == 0) return false;
        // Walk up from `usage` looking for a function-like node, a static
        // block, or a property declaration initializer. Stop at `declContainer`
        // (or at the source file root).
        var current = usage;
        while (current != 0 and current != declContainer) {
            const k = c.binder.ast.getKind(current);
            // Function-like node (not an IIFE) — usage is deferred.
            if (ast_utils.isFunctionLikeNode(c.binder.ast, current)) {
                // IIFE check is simplified: we treat all function-like
                // nodes as deferred, which is conservative (may allow
                // some illegal uses but won't reject legal ones).
                return true;
            }
            // Class static block — usage is deferred.
            if (k == .ClassStaticBlockDeclaration) return true;
            // Property declaration initializer — check if `current` is the
            // initializer of a PropertyDeclaration.
            const parent = c.binder.ast.getNodeParent(current);
            if (parent != 0 and c.binder.ast.getKind(parent) == .PropertyDeclaration) {
                // `current` is inside a property declaration. If it's the
                // initializer, the usage is deferred.
                return true;
            }
            // Decorator — usage is deferred.
            if (parent != 0 and c.binder.ast.getKind(parent) == .Decorator) {
                return true;
            }
            current = parent;
        }
        _ = declaration;
        return false;
    }

    pub fn isImmediatelyUsedInInitializerOfBlockScopedVariable(c: *Checker, declaration: ast_gen.NodeIndex, usage: ast_gen.NodeIndex, declContainer: ast_gen.NodeIndex) bool {
        // Go: switch declaration.Parent.Parent.Kind {
        //   case KindVariableStatement, KindForStatement, KindForOfStatement:
        //     if isSameScopeDescendentOf(usage, declaration, declContainer) { return true }
        //   }
        //   grandparent := declaration.Parent.Parent
        //   return ast.IsForInOrOfStatement(grandparent) && isSameScopeDescendentOf(usage, grandparent.Expression(), declContainer)
        const parent = c.binder.ast.getNodeParent(declaration);
        if (parent == 0) return false;
        const grandparent = c.binder.ast.getNodeParent(parent);
        if (grandparent == 0) return false;
        const gp_kind = c.binder.ast.getKind(grandparent);
        switch (gp_kind) {
            .VariableStatement, .ForStatement, .ForOfStatement => {
                if (c.isSameScopeDescendentOf(usage, declaration, declContainer)) return true;
            },
            else => {},
        }
        // ForIn/ForOf case
        if (gp_kind == .ForInStatement or gp_kind == .ForOfStatement) {
            const expr = c.binder.ast.getNode(grandparent).ForInOrOfStatement.Expression;
            if (expr != 0 and c.isSameScopeDescendentOf(usage, expr, declContainer)) return true;
        }
        return false;
    }

    pub fn isSameScopeDescendentOf(c: *Checker, initial: ast_gen.NodeIndex, parent: ast_gen.NodeIndex, stopAt: ast_gen.NodeIndex) bool {
        // Go: if parent == nil { return false }
        //   for n := initial; n != nil; n = n.Parent {
        //     if n == parent { return true }
        //     if n == stopAt || ast.IsFunctionLike(n) && (GetImmediatelyInvokedFunctionExpression(n) == nil || FunctionFlagsAsyncGenerator) { return false }
        //   }
        //   return false
        if (parent == 0) return false;
        var n = initial;
        while (n != 0) {
            if (n == parent) return true;
            if (n == stopAt) return false;
            if (ast_utils.isFunctionLikeNode(c.binder.ast, n)) return false;
            n = c.binder.ast.getNodeParent(n);
        }
        return false;
    }

    pub fn isPropertyImmediatelyReferencedWithinDeclaration(c: *Checker, declaration: ast_gen.NodeIndex, usage: ast_gen.NodeIndex, stopAtAnyPropertyDeclaration: bool) bool {
        // Go: if usage.End() > declaration.End() { return false }
        //   for node := usage; node != nil && node != declaration; node = node.Parent {
        //     switch node.Kind {
        //     case KindArrowFunction: return false
        //     case KindPropertyDeclaration:
        //       return stopAtAnyPropertyDeclaration && ((IsPropertyDeclaration(declaration) && node.Parent == declaration.Parent) ||
        //         (IsParameterPropertyDeclaration(declaration, declaration.Parent) && node.Parent == declaration.Parent.Parent))
        //     case KindBlock:
        //       switch node.Parent.Kind { case KindMethodDeclaration, KindGetAccessor, KindSetAccessor: return false }
        //     }
        //   }
        //   return true
        // Simplified: skip End() comparison (not always reliable), check node kinds.
        var node = usage;
        while (node != 0 and node != declaration) {
            const k = c.binder.ast.getKind(node);
            switch (k) {
                .ArrowFunction => return false,
                .PropertyDeclaration => {
                    // Simplified: don't check parent relationships for stopAtAnyPropertyDeclaration
                    return stopAtAnyPropertyDeclaration;
                },
                .Block => {
                    const parent = c.binder.ast.getNodeParent(node);
                    if (parent != 0) {
                        const pk = c.binder.ast.getKind(parent);
                        switch (pk) {
                            .MethodDeclaration, .GetAccessor, .SetAccessor => return false,
                            else => {},
                        }
                    }
                },
                else => {},
            }
            node = c.binder.ast.getNodeParent(node);
        }
        return true;
    }

    pub fn getTypeOnlyAliasDeclaration(c: *Checker, sym_idx: ast_gen.SymbolIndex) ast_gen.NodeIndex {
        const sym = c.getSymbolData(sym_idx);
        if (sym.Flags & ast_gen.SymbolFlags.Alias != 0) {
            _ = c.resolveAlias(sym_idx);
            if (c.aliasSymbolLinks.get(sym_idx)) |links| {
                if (links.typeOnlyDeclaration) |decl| {
                    return decl;
                }
            }
        }
        return 0;
    }

    pub fn getTypeOnlyAliasDeclarationEx(c: *Checker, sym_idx: ast_gen.SymbolIndex, meaning: u32) ast_gen.NodeIndex {
        var current_symbol = sym_idx;
        while (true) {
            const sym = c.getSymbolData(current_symbol);
            if (sym.Flags & ast_gen.SymbolFlags.Alias == 0 or sym.Flags & meaning != 0) {
                break;
            }
            const resolved = c.resolveAlias(current_symbol);
            if (c.aliasSymbolLinks.get(current_symbol)) |links| {
                if (links.typeOnlyDeclaration) |decl| {
                    return decl;
                }
            }
            current_symbol = resolved;
        }
        return 0;
    }

    /// Port of `checker.go::getImmediateAliasedSymbol`. Returns the
    /// immediate target of an alias symbol (one-step resolution, not the
    /// fully-resolved alias). Caches via `aliasSymbolLinks`.
    pub fn getImmediateAliasedSymbol(c: *Checker, symbol_: ast_gen.SymbolIndex) ast_gen.SymbolIndex {
        if (symbol_ == 0) return 0;
        if (c.aliasSymbolLinks.getPtr(symbol_)) |links| {
            if (links.immediateTarget) |t| return t;
        }
        // Look up the alias declaration and resolve its target.
        const decl = c.getDeclarationOfAliasSymbol(symbol_) orelse return 0;
        const target = c.getTargetOfAliasDeclaration(decl);
        if (target != 0) {
            if (c.aliasSymbolLinks.getPtr(symbol_)) |links| {
                links.immediateTarget = target;
            } else {
                c.aliasSymbolLinks.put(c.allocator, symbol_, .{ .immediateTarget = target }) catch {};
            }
        }
        return target;
    }

    /// Port of `checker.go::addTypeOnlyDeclarationRelatedInfo`. Adds a
    /// related-info diagnostic to `diagnostic` pointing at the
    /// `typeOnlyDeclaration` (import/export specifier) that introduced
    /// the type-only reference. Returns the (possibly null) diagnostic.
    /// In Zig, the diagnostic system doesn't have a related-info chain,
    /// so we simply report the related info as a separate diagnostic and
    /// return 0 (no new type is created).
    pub fn addTypeOnlyDeclarationRelatedInfo(c: *Checker, diagnostic: ?*const diagnostics_gen.Message, typeOnlyDeclaration: ast_gen.NodeIndex, name_: ast_gen.NodeIndex) types.TypeIndex {
        if (typeOnlyDeclaration == 0) return 0;
        if (diagnostic == null) return 0;
        // Get the name text for the related info message.
        const name_str = if (name_ != 0) ast_utils.getTextOfNode(c.binder.ast, name_) else "<anonymous>";
        // Determine whether this is an export or import context.
        const decl_kind = c.binder.ast.getKind(typeOnlyDeclaration);
        const is_export = decl_kind == .ExportSpecifier or decl_kind == .ExportDeclaration or decl_kind == .NamespaceExport;
        // Report the related info as a separate diagnostic.
        if (is_export) {
            c.reportErrorWithArgs(typeOnlyDeclaration, &diagnostics_gen.X_0_was_exported_here, &.{name_str});
        } else {
            c.reportErrorWithArgs(typeOnlyDeclaration, &diagnostics_gen.X_0_was_imported_here, &.{name_str});
        }
        return 0;
    }

    /// Port of `checker.go::getSymbol`. Looks up `name` in `symbols` with
    /// the given `meaning` (SymbolFlags bitmask). If the found symbol is
    /// an alias, resolves the alias and checks its target flags.
    pub fn getSymbol(c: *Checker, symbols: *const symbol.SymbolTable, name: []const u8, meaning: u32) ast_gen.SymbolIndex {
        if ((meaning & symbol.SymbolFlags.All) == 0) return 0;
        const raw = symbols.get(name) orelse return 0;
        const sym = getMergedSymbol(c, raw);
        if (sym == 0) return 0;
        const flags = c.getSymbolFlags(sym);
        if ((flags & meaning) != 0) return sym;
        if ((flags & symbol.SymbolFlags.Alias) != 0) {
            const target_flags = c.getSymbolFlags(sym);
            if ((target_flags & meaning) != 0) return sym;
        }
        return 0;
    }

    pub fn checkSourceFile(c: *Checker, ctx: ?*anyopaque, sourceFile: ast_gen.NodeIndex, checkUnused: bool) void {
        var links = c.sourceFileLinks.get(sourceFile) orelse types.SourceFileLinks{};
        if (!links.typeChecked) {
            const sf_node = c.binder.ast.getNode(sourceFile);
            if (sf_node == .SourceFile) {
                const stmts = c.binder.ast.getNodeList(sf_node.SourceFile.Statements);
                c.checkSourceElements(stmts);
            }

            c.checkDeferredNodes(ctx);
            // if (utils.isExternalOrCommonJSModule(c.ast, sourceFile)) {
            //     // c.checkExternalModuleExports(sourceFile);
            //     // c.registerForUnusedIdentifiersCheck(sourceFile);
            // }

            // if (!utils.isDeclarationFile(c.ast, sourceFile)) { // && !c.isCanceled()
            //     // c.checkUnusedRenamedBindingElements();
            // }

            links.typeChecked = true;
        }

        if (checkUnused and !links.unusedChecked) {
            // if (!utils.isDeclarationFile(c.ast, sourceFile)) { // && !c.isCanceled()
            //     // c.checkUnusedIdentifiers(links.identifierCheckNodes);
            // }
            links.unusedChecked = true;
        }
        c.sourceFileLinks.put(c.allocator, sourceFile, links) catch {};
    }

    pub fn checkSourceElements(c: *Checker, nodes: []const ast_gen.NodeIndex) void {
        for (nodes) |node| {
            if (node != 0) checkSourceElement(c, node);
        }
    }

    pub fn checkSourceElementUnreachable(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: if !ast.IsPotentiallyExecutableNode(node) { return false }
        //   if c.reportedUnreachableNodes.Has(node) { return true }
        //   if !c.isSourceElementUnreachable(node) { return false }
        //   c.reportedUnreachableNodes.Add(node)
        //   ... (error reporting)
        //   return true
        // Simplified: isPotentiallyExecutableNode and reportedUnreachableNodes not yet wired.
        return c.isSourceElementUnreachable(node);
    }

    pub fn isSourceElementUnreachable(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: if node.Flags&ast.NodeFlagsUnreachable != 0 {
        //   switch node.Kind {
        //   case KindEnumDeclaration: return !ast.IsEnumConst(node) || c.compilerOptions.ShouldPreserveConstEnums()
        //   case KindModuleDeclaration: return ast.IsInstantiatedModule(node, c.compilerOptions.ShouldPreserveConstEnums())
        //   default: return true
        //   }
        // } else if flowNode := node.FlowNodeData().FlowNode; flowNode != nil {
        //   return !c.isReachableFlowNode(flowNode)
        // }
        // return false
        const flags = c.binder.ast.getNodeFlags(node);
        if ((flags & ast.NodeFlagsUnreachable) != 0) {
            const node_kind = c.binder.ast.getKind(node);
            switch (node_kind) {
                .EnumDeclaration => return true, // IsEnumConst and preserveConstEnums not yet wired
                .ModuleDeclaration => return isInstantiatedModule(node, false),
                else => return true,
            }
        }
        // Flow node reachability check not yet wired.
        return false;
    }

    /// Port of checker.go::checkDeferredNodes. Iterates all deferred
    /// nodes and checks each one. Called after the main source file
    /// traversal completes.
    pub fn checkDeferredNodes(c: *Checker, context: ?*anyopaque) void {
        _ = context;
        // Process all deferred nodes. We take ownership of the list to
        // allow new deferrals during processing.
        const nodes = c.deferredNodes.toOwnedSlice(c.allocator) catch return;
        defer c.allocator.free(nodes);
        for (nodes) |node| {
            if (node != 0) checkSourceElement(c, node);
        }
    }

    /// Port of checker.go::checkDeferredNode. Checks a single deferred
    /// node immediately (used when a deferred node needs to be checked
    /// eagerly, e.g., during type query resolution).
    pub fn checkDeferredNode(c: *Checker, node: ast_gen.NodeIndex) void {
        if (node == 0) return;
        checkSourceElement(c, node);
    }

    /// Port of `checker.go::checkJSDocComments`. Iterates JSDoc comment
    /// nodes attached to `node` and checks each one. JSDoc checking is
    /// minimal: it only validates @link references for unused-identifier
    /// tracking. Full JSDoc type checking is deferred to the JSDoc
    /// checker module.
    pub fn checkJSDocComments(c: *Checker, node: ast_gen.NodeIndex) void {
        if (node == 0) return;
        // In Zig, JSDoc comment nodes are not yet fully wired into the AST.
        // A full implementation would iterate `node.Comments()` and call
        // `checkJSDocComment` for each JSDoc node. Conservative: no-op.
        _ = c;
    }

    /// Port of `checker.go::checkJSDocComment`. Checks a single JSDoc
    /// comment node. Currently a no-op since JSDoc @link reference
    /// tracking requires the full JSDoc AST node structure.
    pub fn checkJSDocComment(c: *Checker, node: ast_gen.NodeIndex) void {        _ = c;
        _ = node;
        // No-op: full implementation not yet wired.
    }

    /// Port of `checker.go::checkJSDocTypeIsInJsFile`. Reports an error if
    /// a JSDoc type annotation (e.g., `JSDocNullableType`, `JSDocNonNullableType`,
    /// or any other JSDoc type node) appears in a non-JS file. JSDoc type
    /// syntax is only valid inside JSDoc comments in .js/.jsx/.mjs/.cjs files.
    pub fn checkJSDocTypeIsInJsFile(c: *Checker, node: ast_gen.NodeIndex) void {
        if (node == 0) return;
        if (!ast_utils.isInJSFile(c.binder.ast, node)) {
            // Report that JSDoc types can only be used in documentation comments.
            c.reportError(node, &diagnostics_gen.JSDoc_types_can_only_be_used_inside_documentation_comments);
        }
    }

    /// Port of checker.go::checkTypeParameterDeferred. Deferred checking
    /// of a type parameter — resolves constraint and default type.
    /// Simplified: delegates to checkTypeParameter.
    pub fn checkTypeParameterDeferred(c: *Checker, node: ast_gen.NodeIndex) void {
        checkSourceElement(c, node);
    }

    /// Port of checker.go::shouldCheckErasableSyntax. Full Go logic.
    pub fn shouldCheckErasableSyntax(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: return c.compilerOptions.ErasableSyntaxOnly.IsTrue() && !ast.IsInJSFile(node)
        const not_js = !ast_utils.isInJSFile(c.binder.ast, node);
        if (c.compilerOptions) |opts| {
            return opts.erasableSyntaxOnly != null and opts.erasableSyntaxOnly.? and not_js;
        }
        return false;
    }

    /// Port of `checker.go::checkAsyncFunctionReturnType`. Validates
    /// that an async function's return type is a Promise or a type
    /// compatible with Promise. Reports an error if the return type is
    /// not a valid Promise reference. Conservative: only checks if a
    /// global Promise type is available and the return type references it.
    pub fn checkAsyncFunctionReturnType(c: *Checker, node: ast_gen.NodeIndex, return_type_node: ast_gen.NodeIndex) void {
        if (return_type_node == 0) return;
        const return_type = c.getTypeFromTypeNode(return_type_node);
        if (c.isErrorType(return_type)) return;
        // Look up the global Promise type. If not available, skip the check
        // (the program may not include lib.d.ts).
        const global_promise = c.getGlobalType("Promise", 1, false);
        if (global_promise == 0 or global_promise == (c.emptyGenericTypeIndex orelse 0)) return;
        // Check if the return type is a reference to the global Promise type.
        // Conservative: check if the return type's symbol is the Promise symbol.
        const ret_sym = c.getSymbolOfType(return_type);
        const promise_sym = c.getSymbolOfType(global_promise);
        if (ret_sym != 0 and promise_sym != 0 and ret_sym == promise_sym) return;
        // Not a Promise reference — report an error suggesting `Promise<T>`.
        const awaited_type = c.getAwaitedTypeNoAlias(return_type);
        const awaited_str = c.typeToString(awaited_type, node, 0, null);
        c.reportErrorWithArgs(return_type_node, &diagnostics_gen.The_return_type_of_an_async_function_or_method_must_be_the_global_Promise_T_type_Did_you_mean_to_write_Promise_0, &.{awaited_str});
    }

    /// Port of `checker.go::findFirstSuperCall`. Walks the children of
    /// `node` looking for the first `super(...)` call. Stops at function-like
    /// boundaries.
    pub fn findFirstSuperCall(c: *Checker, node: ast_gen.NodeIndex) ast_gen.NodeIndex {
        if (node == 0) return 0;
        var result: ast_gen.NodeIndex = 0;
        const Context = struct {
            chk: *Checker,
            found: *ast_gen.NodeIndex,
        };
        var ctx = Context{ .chk = c, .found = &result };
        const visit = struct {
            fn visit(ctx_in: Context, n: ast_gen.NodeIndex) bool {
                if (utils.isSuperCall(ctx_in.chk.binder.ast, n)) {
                    ctx_in.found.* = n;
                    return true;
                }
                if (ast_utils.isFunctionLikeDeclaration(ctx_in.chk.binder.ast, n) and n != node) {
                    return false;
                }
                // Recurse into children
                _ = ast_utils.forEachChildBool(ctx_in.chk.binder.ast, n, ctx_in, visit);
                return ctx_in.found.* != 0;
            }
        }.visit;
        _ = visit(&ctx, node);
        _ = &ctx;
        return result;
    }

    pub fn isInstancePropertyWithInitializerOrPrivateIdentifierProperty(c: *Checker, n: ast_gen.NodeIndex) bool {
        // Go: return ast.IsPrivateIdentifierClassElementDeclaration(n) || ast.IsPropertyDeclaration(n) && !ast.IsStatic(n) && n.Initializer() != nil
        if (ast_utils.isPrivateIdentifierClassElementDeclaration(c.binder.ast, n)) return true;
        if (!ast_utils.isPropertyDeclaration(c.binder.ast, n)) return false;
        if (ast_utils.isStatic(c.binder.ast, n)) return false;
        const init_node: ?ast_gen.NodeIndex = c.binder.ast.getNode(n).PropertyDeclaration.Initializer;
        return init_node != null;
    }

    pub fn superCallIsRootLevelInConstructor(c: *Checker, superCall: ast_gen.NodeIndex, body: ast_gen.NodeIndex) bool {
        // Go: superCallParent := ast.WalkUpParenthesizedExpressions(superCall.Parent)
        //     return ast.IsExpressionStatement(superCallParent) && superCallParent.Parent == body
        var current = c.binder.ast.getNodeParent(superCall);
        while (current != 0 and c.binder.ast.getKind(current) == .ParenthesizedExpression) {
            current = c.binder.ast.getNodeParent(current);
        }
        if (current == 0) return false;
        if (c.binder.ast.getKind(current) != .ExpressionStatement) return false;
        return c.binder.ast.getNodeParent(current) == body;
    }

    pub fn nodeImmediatelyReferencesSuperOrThis(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: switch node.Kind {
        //   case SuperKeyword, ThisKeyword: return true
        //   case ArrowFunction, FunctionDeclaration, FunctionExpression, PropertyDeclaration: return false
        //   case Block: switch node.Parent.Kind {
        //     case Constructor, MethodDeclaration, GetAccessor, SetAccessor: return false
        //   }
        // }
        // return node.ForEachChild(nodeImmediatelyReferencesSuperOrThis)
        const node_kind = c.binder.ast.getKind(node);
        switch (node_kind) {
            .SuperKeyword, .ThisKeyword => return true,
            .ArrowFunction, .FunctionDeclaration, .FunctionExpression, .PropertyDeclaration => return false,
            .Block => {
                const parent = c.binder.ast.getNodeParent(node);
                if (parent != 0) {
                    const pk = c.binder.ast.getKind(parent);
                    switch (pk) {
                        .Constructor, .MethodDeclaration, .GetAccessor, .SetAccessor => return false,
                        else => {},
                    }
                }
            },
            else => {},
        }
        // ForEachChild: iterate children manually (simple implementation using
        // visitor pattern). We rely on getChildren API if available.
        const children = c.binder.ast.getChildren(node) catch return false;
        for (children) |child| {
            if (nodeImmediatelyReferencesSuperOrThis(c, child)) return true;
        }
        return false;
    }

    /// Port of checker.go::checkTypeReferenceOrImport. Checks a type
