    /// Port of `checker.go::arePropertiesAbstractOrInterface`. Returns true
    /// if all (or some, for synthetic symbols) declarations of `base` are
    /// abstract or from an interface.
    pub fn arePropertiesAbstractOrInterface(c: *Checker, base: ast_gen.SymbolIndex, base_declaration_flags: u32) bool {
        if (base == 0 or base >= c.binder.symbols.items.len) return false;
        const sym = c.binder.symbols.items[base];
        const is_synthetic = (sym.CheckFlags & types.CheckFlags.Synthetic) != 0;
        for (sym.Declarations.items) |decl| {
            const result = c.isPropertyAbstractOrInterface(decl, base_declaration_flags);
            if (is_synthetic) {
                // Synthetic: return true if ANY declaration is abstract/interface
                if (result) return true;
            } else {
                // Non-synthetic: return false if ANY declaration is NOT abstract/interface
                if (!result) return false;
            }
        }
        return !is_synthetic; // synthetic returns false if none matched; non-synthetic returns true if all matched
    }

    /// Port of `checker.go::isPropertyAbstractOrInterface`. Returns true if
    /// the declaration's parent is an interface, or if it's an abstract
    /// property without an initializer.
    pub fn isPropertyAbstractOrInterface(c: *Checker, declaration: ast_gen.NodeIndex, base_declaration_flags: u32) bool {
        if (declaration == 0) return false;
        const tree = c.binder.ast;
        const parent = tree.getNodeParent(declaration);
        if (parent != 0 and ast_utils.isInterfaceDeclaration(tree, parent)) return true;
        if ((base_declaration_flags & ast_utils.ModifierFlags.Abstract) != 0) {
            if (!ast_utils.isPropertyDeclaration(tree, declaration)) return true;
            return ast_utils.getInitializerOfNode(tree, declaration) == 0;
        }
        return false;
    }

    /// Port of checker.go::checkMembersForOverrideModifier. Validates
    /// that override modifiers are correct for class members. Simplified: no-op.
    /// Port of `checker.go::checkMembersForOverrideModifier`. Iterates
    /// class members, calling `checkMemberForOverrideModifier` for each
    /// non-ambient member (including constructor parameter properties).
    pub fn checkMembersForOverrideModifier(c: *Checker, node: ast_gen.NodeIndex, t: types.TypeIndex, type_with_this: types.TypeIndex, static_type: types.TypeIndex) void {
        // Get base type with `this` argument.
        var base_with_this: types.TypeIndex = 0;
        const extends_elem = ast_utils.getExtendsHeritageClauseElement(c.binder.ast, node);
        if (extends_elem != 0) {
            // getBaseTypes is still partially stubbed; conservatively skip.
            _ = &base_with_this;
        }
        const base_static_type = c.getBaseConstructorTypeOfClass(t);
        // Iterate class members.
        const members_list: ?ast_gen.NodeListIndex = switch (c.binder.ast.getNode(node)) {
            .ClassDeclaration => |n| n.Members,
            .ClassExpression => |n| n.Members,
            else => null,
        };
        if (members_list) |ml| {
            const members = c.binder.ast.getNodeList(ml);
            for (members) |member| {
                if (member == 0) continue;
                if (ast_utils.hasAmbientModifier(c.binder.ast, member)) continue;
                const mk = c.binder.ast.getKind(member);
                if (mk == .Constructor) {
                    // Check parameter properties.
                    const params_list = c.binder.ast.getNode(member).Constructor.Parameters;
                    if (params_list != 0) {
                        const params = c.binder.ast.getNodeList(params_list);
                        for (params) |param| {
                            if (param != 0 and ast_utils.isParameterPropertyDeclaration(c.binder.ast, param, member)) {
                                c.checkMemberForOverrideModifier(node, static_type, base_static_type, base_with_this, t, type_with_this, param);
                            }
                        }
                    }
                } else {
                    c.checkMemberForOverrideModifier(node, static_type, base_static_type, base_with_this, t, type_with_this, member);
                }
            }
        }
    }

    /// Port of checker.go::checkMemberForOverrideModifier. Validates
    /// that a single member's override modifier is correct. Simplified: no-op.
    /// Port of `checker.go::checkMemberForOverrideModifier`. Validates
    /// that a single member's `override` modifier is correct: the base
    /// class must exist, the member must be declared in the base, and
    /// in `noImplicitOverride` mode, overriding members must have `override`.
    pub fn checkMemberForOverrideModifier(c: *Checker, node: ast_gen.NodeIndex, static_type: types.TypeIndex, base_static_type: types.TypeIndex, base_with_this: types.TypeIndex, t: types.TypeIndex, type_with_this: types.TypeIndex, member: ast_gen.NodeIndex) void {
        if (member == 0) return;
        const member_has_override = ast_utils.hasSyntacticModifier(c.binder.ast, member, ast_utils.ModifierFlags.Override);
        // No base class — error if override modifier is present.
        if (base_with_this == 0) {
            if (member_has_override) {
                const t_str = c.typeToString(t, 0, 0, null);
                c.reportErrorWithArgs(member, &diagnostics_gen.This_member_cannot_have_an_override_modifier_because_its_containing_class_0_does_not_extend_another_class, &.{t_str});
            }
            return;
        }
        // Skip if no override modifier and noImplicitOverride is off.
        if (!member_has_override) return;
        // Get the symbol of the member declaration.
        const sym = c.getSymbolOfDeclaration(member);
        if (sym == 0) return;
        const sym_data = c.binder.symbols.items[sym];
        const member_is_static = ast_utils.isStatic(c.binder.ast, member);
        const this_type = if (member_is_static) static_type else type_with_this;
        const prop = c.getPropertyOfType(this_type, sym_data.Name) orelse return;
        _ = prop;
        // Check base type for the property.
        const base_type = if (member_is_static) base_static_type else base_with_this;
        const base_prop = c.getPropertyOfType(base_type, sym_data.Name);
        if (base_prop == 0 and member_has_override) {
            // Suggest a similar name from the base type.
            const suggestion = c.getSuggestedSymbolForNonexistentClassMember(member, base_type);
            if (suggestion != 0) {
                const base_str = c.typeToString(base_with_this, 0, 0, null);
                const sugg_str = c.symbolToString(suggestion);
                c.reportErrorWithArgs(member, &diagnostics_gen.This_member_cannot_have_an_override_modifier_because_it_is_not_declared_in_the_base_class_0_Did_you_mean_1, &.{ base_str, sugg_str });
            } else {
                const base_str = c.typeToString(base_with_this, 0, 0, null);
                c.reportErrorWithArgs(member, &diagnostics_gen.This_member_cannot_have_an_override_modifier_because_it_is_not_declared_in_the_base_class_0, &.{base_str});
            }
            return;
        }
        _ = node;
    }

    /// Port of `checker.go::getSuggestedSymbolForNonexistentClassMember`.
    /// Returns a spelling suggestion for a missing class member from the
    /// properties of `baseType`.
    pub fn getSuggestedSymbolForNonexistentClassMember(c: *Checker, name_: ast_gen.NodeIndex, baseType: types.TypeIndex) ast_gen.SymbolIndex {
        if (name_ == 0 or baseType == 0) return 0;
        const text = ast_utils.getTextOfNode(c.binder.ast, name_);
        const props = c.getPropertiesOfType(baseType);
        var best: ast_gen.SymbolIndex = 0;
        var best_distance: usize = std.math.maxInt(usize);
        for (props) |prop| {
            const prop_flags = c.getSymbolFlags(prop);
            if ((prop_flags & symbol.SymbolFlags.ClassMember) == 0) continue;
            const prop_name = c.getSymbolName(prop);
            if (prop_name.len == 0) continue;
            if (std.ascii.eqlIgnoreCase(prop_name, text)) return prop;
            const dist = levenshteinDistance(text, prop_name);
            if (dist < best_distance) {
                best_distance = dist;
                best = prop;
            }
        }
        if (best != 0 and best_distance <= 2) return best;
        return 0;
    }

