    /// Port of `checker.go::addDeprecatedSuggestionWithSignature`. Reports
    /// a deprecation diagnostic with a signature string, then adds the
    /// deprecated suggestion.
    pub fn addDeprecatedSuggestionWithSignature(c: *Checker, location: ast_gen.NodeIndex, declaration: ast_gen.NodeIndex, deprecatedEntity: ast_gen.SymbolIndex, signatureString: []const u8) void {
        // Get the deprecated entity name.
        const entity_name: []const u8 = if (deprecatedEntity != 0 and deprecatedEntity < c.binder.symbols.items.len)
            c.binder.symbols.items[deprecatedEntity].Name
        else
            "";
        const msg: *const diagnostics_gen.Message = if (entity_name.len > 0)
            &diagnostics_gen.The_signature_0_of_1_is_deprecated
        else
            &diagnostics_gen.X_0_is_deprecated;
        c.reportErrorWithArgs(location, msg, &.{ signatureString, entity_name });
        c.addDeprecatedSuggestionWorker(&[_]ast_gen.NodeIndex{declaration}, msg);
    }

    pub fn isSymbolOrSymbolForCall(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: if !ast.IsCallExpression(node) { return false }
        //   left := node.Expression()
        //   if ast.IsPropertyAccessExpression(left) && left.Name().Text() == "for" { left = left.Expression() }
        //   if !ast.IsIdentifier(left) || left.Text() != "Symbol" { return false }
        //   globalESSymbol := c.getGlobalESSymbolConstructorSymbolOrNil()
        //   if globalESSymbol == nil { return false }
        //   return globalESSymbol == c.resolveName(left, "Symbol", ast.SymbolFlagsValue, nil, false, false)
        // Simplified: check CallExpression with Symbol/Symbol.for expression.
        // getGlobalESSymbolConstructorSymbolOrNil not yet wired; check name only.
        if (c.binder.ast.getKind(node) != .CallExpression) return false;
        var left = c.binder.ast.getNode(node).CallExpression.Expression;
        if (left != 0 and c.binder.ast.getKind(left) == .PropertyAccessExpression) {
            const name_node = c.binder.ast.getNode(left).PropertyAccessExpression.name;
            if (name_node != 0 and c.binder.ast.getKind(name_node) == .Identifier) {
                const name_text = c.binder.ast.getNode(name_node).Identifier.Text;
                if (std.mem.eql(u8, name_text, "for")) {
                    left = c.binder.ast.getNode(left).PropertyAccessExpression.Expression;
                }
            }
        }
        if (left == 0 or c.binder.ast.getKind(left) != .Identifier) return false;
        const left_text = c.binder.ast.getNode(left).Identifier.Text;
        return std.mem.eql(u8, left_text, "Symbol");
    }

    /// Port of `checker.go::resolveSignature`. Resolves the call
    /// signature for a call-like expression (CallExpression, NewExpression,
    /// TaggedTemplateExpression, Decorator). Delegates to `resolveCallExpression`.
    pub fn resolveSignature(c: *Checker, node: ast_gen.NodeIndex, candidatesOutArray: ?*std.ArrayListUnmanaged(types.SignatureIndex), checkMode: CheckMode) types.SignatureIndex {
        return c.resolveCallExpression(node, candidatesOutArray, checkMode);
    }

    pub fn resolveCallExpression(c: *Checker, node: ast_gen.NodeIndex, candidatesOutArray: ?*std.ArrayListUnmanaged(types.SignatureIndex), checkMode: CheckMode) types.SignatureIndex {
        const callNodeKind = std.meta.activeTag(c.binder.ast.getNode(node));
        var targetExpr: ast_gen.NodeIndex = 0;
        if (callNodeKind == .CallExpression) {
            targetExpr = c.binder.ast.getNode(node).CallExpression.Expression;
        } else if (callNodeKind == .NewExpression) {
            targetExpr = c.binder.ast.getNode(node).NewExpression.Expression;
        } else if (callNodeKind == .TaggedTemplateExpression) {
            targetExpr = c.binder.ast.getNode(node).TaggedTemplateExpression.Tag;
        } else {
            return 0;
        }
        
        const targetType = c.checkExpressionAdHoc(targetExpr) catch return 0;
        const sigKind: types.SignatureKind = if (callNodeKind == .NewExpression) .Construct else .Call;
        const candidatesSlice = c.getSignaturesOfType(targetType, sigKind);
        
        const signatures = c.allocator.alloc(types.SignatureIndex, candidatesSlice.len) catch unreachable;
        defer c.allocator.free(signatures);
        if (candidatesSlice.len > 0) {
            @memcpy(signatures, c.resolvedSignaturesPool.items[candidatesSlice.start .. candidatesSlice.start + candidatesSlice.len]);
        }
        
        return c.resolveCall(node, signatures, candidatesOutArray, checkMode, 0, 0);
    }

