    /// Port of `checker.go::hasCorrectArity`. Returns true if `args`
    /// has the correct arity for `signature`. Simplified: checks arg
    /// count against parameter count and min argument count.
    pub fn hasCorrectArity(c: *Checker, node: ast_gen.NodeIndex, args: []const ast_gen.NodeIndex, signature: types.SignatureIndex, signatureHelpTrailingComma: bool) bool {
        if (signature >= c.signatures.items.len) return false;
        const sig = &c.signatures.items[signature];
        // Get effective parameter count and minimum argument count.
        const param_count: i32 = @intCast(sig.parametersLen);
        const min_args: i32 = sig.minArgumentCount;
        const has_rest = (sig.flags & types.SignatureFlags.HasRestParameter) != 0;
        // Determine arg count based on node kind.
        var arg_count: i32 = @intCast(args.len);
        if (signatureHelpTrailingComma) arg_count += 1;
        const node_kind = c.binder.ast.getKind(node);
        // For decorators and binary expressions, arg count is 1.
        if (node_kind == .Decorator or node_kind == .BinaryExpression) {
            arg_count = 1;
        }
        // Too many arguments (without rest) → incorrect arity.
        if (!has_rest and arg_count > param_count) return false;
        // Too few arguments → check if remaining params accept void.
        if (arg_count < min_args) {
            // Conservative: return false (incorrect arity).
            // Full implementation would check if remaining params accept void.
            return false;
        }
        return true;
    }

    pub fn acceptsVoid(c: *Checker, t: types.TypeIndex) bool {
        // Go: return t.flags&TypeFlagsVoid != 0
        return (c.typesList.items[t].flags & types.TypeFlags.Void) != 0;
    }

    pub fn getDecoratorArgumentCount(c: *Checker, node: ast_gen.NodeIndex, signature: types.SignatureIndex) i32 {
        // Go: if c.compilerOptions.ExperimentalDecorators.IsTrue() { return c.getLegacyDecoratorArgumentCount(node, signature) }
        //   return min(max(c.getParameterCount(signature), 1), 2)
        // Simplified: ExperimentalDecorators not yet wired; use modern path.
        const sig = c.signatures.items[signature];
        const param_count: i32 = @intCast(sig.parametersLen);
        const max_val: i32 = if (param_count > 1) param_count else 1;
        const min_val: i32 = if (max_val < 2) max_val else 2;
        _ = node;
        return min_val;
    }

    pub fn getLegacyDecoratorArgumentCount(c: *Checker, node: ast_gen.NodeIndex, signature: types.SignatureIndex) i32 {
        // Go: switch node.Parent.Kind {
        //   case KindClassDeclaration, KindClassExpression: return 1
        //   case KindPropertyDeclaration:
        //     if ast.HasAccessorModifier(node.Parent) { return 3 }
        //     return 2
        //   case KindMethodDeclaration, KindGetAccessor, KindSetAccessor:
        //     if len(signature.parameters) <= 2 { return 2 }
        //     return 3
        //   case KindParameter: return 3
        // }
        // panic(...)
        const parent = c.binder.ast.getNodeParent(node);
        if (parent == 0) return 1;
        const pk = c.binder.ast.getKind(parent);
        switch (pk) {
            .ClassDeclaration, .ClassExpression => return 1,
            .PropertyDeclaration => return 2, // HasAccessorModifier not yet wired
            .MethodDeclaration, .GetAccessor, .SetAccessor => {
                const sig = c.signatures.items[signature];
                if (sig.parametersLen <= 2) return 2;
                return 3;
            },
            .Parameter => return 3,
            else => return 1,
        }
    }

    pub fn hasCorrectTypeArgumentArity(c: *Checker, signature: types.SignatureIndex, typeArguments: ast_gen.NodeIndex) bool {
        // Go: numTypeParameters := len(signature.typeParameters)
        //   minTypeArgumentCount := c.getMinTypeArgumentCount(signature.typeParameters)
        //   return len(typeArguments) == 0 || len(typeArguments) >= minTypeArgumentCount && len(typeArguments) <= numTypeParameters
        // Simplified: signature.typeParameters not directly accessible as slice.
        // Use typeParametersLen from Signature struct.
        const sig = c.signatures.items[signature];
        const num_type_params: usize = sig.typeParametersLen;
        // typeArguments is a NodeIndex (list index) — count not directly available.
        // Conservative: return true if typeArguments == 0 (no type args supplied).
        if (typeArguments == 0) return true;
        // Without proper type argument count, conservative: check against typeParametersLen.
        return num_type_params > 0; // Conservative: assume correct if there are type params
    }

    /// Port of checker.go::checkTypeArguments. Validates type arguments
    /// against type parameter constraints. Simplified: returns false.
    /// Port of `checker.go::checkTypeArguments`. Validates that type
    /// arguments satisfy the constraints of the signature's type
    /// parameters. Returns true if all type arguments are valid.
    pub fn checkTypeArguments(c: *Checker, signature: types.SignatureIndex, type_argument_nodes: ast_gen.NodeIndex, report_errors: bool, head_message: ?*const diagnostics_gen.Message) bool {
        if (signature >= c.signatures.items.len) return false;
        const sig = &c.signatures.items[signature];
        // Get type parameters.
        const type_params = if (sig.typeParametersLen > 0)
            c.signatureTypeParameters.items[sig.typeParametersStart .. sig.typeParametersStart + sig.typeParametersLen]
        else
            &[_]types.TypeIndex{};
        if (type_params.len == 0) return true; // No type params → nothing to check.
        // Get type argument nodes as a list.
        var type_arg_types = std.ArrayListUnmanaged(types.TypeIndex).empty;
        defer type_arg_types.deinit(c.allocator);
        if (type_argument_nodes != 0) {
            const nodes = c.binder.ast.getNodeList(type_argument_nodes);
            for (nodes) |node| {
                type_arg_types.append(c.allocator, c.getTypeFromTypeNode(node)) catch {};
            }
        }
        // Fill missing type arguments.
        const filled = c.fillMissingTypeArguments(type_arg_types.items, type_params, 0, false);
        // Check each type argument against its constraint.
        for (filled, 0..) |type_arg, i| {
            if (i >= type_params.len) break;
            const constraint = c.getConstraintOfTypeParameter(type_params[i]);
            if (constraint) |con| {
                if (!c.isTypeAssignableTo(type_arg, con)) {
                    if (report_errors) {
                        const arg_str = c.typeToString(type_arg, 0, 0, null);
                        const con_str = c.typeToString(con, 0, 0, null);
                        const msg = head_message orelse &diagnostics_gen.Type_0_does_not_satisfy_the_constraint_1;
                        c.reportErrorWithArgs(0, msg, &.{ arg_str, con_str });
                    }
                    return false;
                }
            }
        }
        return true;
    }

