    /// Port of `checker.go::getCandidateForOverloadFailure`. Returns the
    /// best candidate for overload failure error reporting.
    pub fn getCandidateForOverloadFailure(c: *Checker, node: ast_gen.NodeIndex, candidates: []const types.SignatureIndex, args: []const ast_gen.NodeIndex, hasCandidatesOutArray: bool, checkMode: CheckMode) types.SignatureIndex {
        c.checkNodeDeferred(node);
        var has_type_params = false;
        for (candidates) |sig| {
            if (sig < c.signatures.items.len and c.signatures.items[sig].typeParametersLen > 0) {
                has_type_params = true;
                break;
            }
        }
        if (hasCandidatesOutArray or candidates.len == 1 or has_type_params) {
            return c.pickLongestCandidateSignature(node, candidates, args, checkMode);
        }
        return c.createUnionOfSignaturesForOverloadFailure(candidates);
    }

    /// Port of `checker.go::pickLongestCandidateSignature`. Returns the
    /// longest candidate signature via getLongestCandidateIndex.
    pub fn pickLongestCandidateSignature(c: *Checker, node: ast_gen.NodeIndex, candidates: []const types.SignatureIndex, args: []const ast_gen.NodeIndex, checkMode: CheckMode) types.SignatureIndex {
        _ = node;
        _ = checkMode;
        if (candidates.len == 0) return 0;
        const arg_count: i32 = @intCast(args.len);
        const best_index = c.getLongestCandidateIndex(candidates, arg_count);
        if (best_index >= 0 and @as(usize, @intCast(best_index)) < candidates.len) {
            return candidates[@intCast(best_index)];
        }
        return 0;
    }

    pub fn getLongestCandidateIndex(c: *Checker, candidates: []const types.SignatureIndex, argsCount: i32) i32 {
        // Go: maxParamsIndex := -1
        //   maxParams := -1
        //   for i, candidate := range candidates {
        //     paramCount := c.getParameterCount(candidate)
        //     if c.hasEffectiveRestParameter(candidate) || paramCount >= argsCount { return i }
        //     if paramCount > maxParams { maxParams = paramCount; maxParamsIndex = i }
        //   }
        //   return maxParamsIndex
        // Simplified: getParameterCount and hasEffectiveRestParameter need Signature
        // param access. Use parametersLen from Signature struct.
        var max_params_index: i32 = -1;
        var max_params: i32 = -1;
        for (candidates, 0..) |candidate, i| {
            const sig = c.signatures.items[candidate];
            const param_count: i32 = @intCast(sig.parametersLen);
            // hasEffectiveRestParameter: check last param's DotDotDotToken
            const has_rest = c.hasRestParameter(sig.declaration);
            if (has_rest or param_count >= argsCount) return @intCast(i);
            if (param_count > max_params) {
                max_params = param_count;
                max_params_index = @intCast(i);
            }
        }
        return max_params_index;
    }

