    /// Port of `checker.go::checkArithmeticOperandType`. Returns true if
    /// `t` is assignable to `number | bigint`. Otherwise, reports an error
    /// and optionally suggests `await` if the awaited type would be valid.
    pub fn checkArithmeticOperandType(c: *Checker, operand: ast_gen.NodeIndex, t: types.TypeIndex, diagnostic: diagnostics_gen.Message, isAwaitValid: bool) bool {
        if (c.isTypeAssignableTo(t, c.numberOrBigIntTypeIndex orelse 0)) return true;
        var awaited_type: types.TypeIndex = 0;
        if (isAwaitValid) {
            awaited_type = c.getAwaitedTypeOfPromise(t);
        }
        const maybe_missing_await = awaited_type != 0 and c.isTypeAssignableTo(awaited_type, c.numberOrBigIntTypeIndex orelse 0);
        c.errorAndMaybeSuggestAwait(operand, maybe_missing_await, &diagnostic);
        return false;
    }

    /// Port of `checker.go::checkForDisallowedESSymbolOperand`. Reports
    /// an error if either operand is an ES symbol-like type in a binary
    /// expression that doesn't allow symbols. Returns false if an error
    /// was reported, true otherwise.
    pub fn checkForDisallowedESSymbolOperand(c: *Checker, left: ast_gen.NodeIndex, right: ast_gen.NodeIndex, leftType: types.TypeIndex, rightType: types.TypeIndex, operator: u32) bool {
        _ = operator;
        var offending: ast_gen.NodeIndex = 0;
        if (c.maybeTypeOfKindConsideringBaseConstraint(leftType, types.TypeFlags.ESSymbolLike)) {
            offending = left;
        } else if (c.maybeTypeOfKindConsideringBaseConstraint(rightType, types.TypeFlags.ESSymbolLike)) {
            offending = right;
        }
        if (offending != 0) {
            c.reportErrorWithArgs(offending, &diagnostics_gen.The_0_operator_cannot_be_applied_to_type_symbol, &.{""});
            return false;
        }
        return true;
    }

    /// Port of checker.go::checkNaNEquality. Reports warnings when NaN
    /// is compared with === or !==. Simplified: no-op.
    /// Port of `checker.go::checkNaNEquality`. Reports a warning when
    /// NaN is compared with === or !==, suggesting `Number.isNaN()` instead.
    pub fn checkNaNEquality(c: *Checker, error_node: ast_gen.NodeIndex, operator: ast_gen.NodeIndex, left: ast_gen.NodeIndex, right: ast_gen.NodeIndex) void {
        const left_skip = ast_utils.skipParentheses(c.binder.ast, left);
        const right_skip = ast_utils.skipParentheses(c.binder.ast, right);
        const is_left_nan = c.isGlobalNaN(left_skip);
        const is_right_nan = c.isGlobalNaN(right_skip);
        if (!is_left_nan and !is_right_nan) return;
        // Report "This condition will always return 'false'" (for === / ==) or 'true' (for !== / !=).
        const op_kind: @import("../ast/kind.zig").Kind = @enumFromInt(operator);
        const is_strict_eq = op_kind == .EqualsEqualsEqualsToken or op_kind == .EqualsEqualsToken;
        const result_str: []const u8 = if (is_strict_eq) "false" else "true";
        c.reportErrorWithArgs(error_node, &diagnostics_gen.This_condition_will_always_return_0, &.{result_str});
        if (is_left_nan and is_right_nan) return;
        // Suggest Number.isNaN(...) for the non-NaN side.
        const location = if (is_left_nan) right else left;
        const location_skip = ast_utils.skipParentheses(c.binder.ast, location);
        var entity_name: []const u8 = "...";
        if (ast_utils.isEntityNameExpression(c.binder.ast, location_skip)) {
            entity_name = ast_utils.getTextOfNode(c.binder.ast, location_skip);
        }
        var suggestion_buf: [256]u8 = undefined;
        const op_str: []const u8 = if (op_kind == .ExclamationEqualsEqualsToken or op_kind == .ExclamationEqualsToken) "!" else "";
        const suggestion = std.fmt.bufPrint(&suggestion_buf, "{s}Number.isNaN({s})", .{ op_str, entity_name }) catch entity_name;
        _ = suggestion;
        // Simplified: skip related info (would need AddRelatedInfo).
    }

    /// Port of checker.go::isGlobalNaN. Full Go logic.
    pub fn isGlobalNaN(c: *Checker, expr: ast_gen.NodeIndex) bool {
        if (c.binder.ast.getKind(expr) != .Identifier) return false;
        const text = @import("../ast/ast_utils.zig").getText(c.binder.ast, expr);
        if (!std.mem.eql(u8, text, "NaN")) return false;
        // Check if resolved symbol is the global NaN
        const resolved = getResolvedSymbol(c, expr);
        const global_nan = c.resolveName(null, "NaN", @import("../ast/symbol.zig").SymbolFlags.Value, null, false, false);
        return global_nan != 0 and global_nan != c.unknownSymbol and resolved == global_nan;
    }

    /// Port of checker.go::isTypeEqualityComparableTo. Full Go logic.
    pub fn isTypeEqualityComparableTo(c: *Checker, source: types.TypeIndex, target: types.TypeIndex) bool {
        if (target == 0 or target >= c.typesList.items.len) return false;
        const target_flags = c.typesList.items[target].flags;
        if ((target_flags & types.TypeFlags.Nullable) != 0) return true;
        // Would check isTypeComparableTo — simplified: check if same type
        return source == target;
    }

    pub const PredicateSemantics = enum(u32) {
        None = 0,
        Always = 1,
        Never = 2,
        Sometimes = 3,
    };

    pub fn checkTruthinessOfType(c: *Checker, t: types.TypeIndex, node: ast_gen.NodeIndex) types.TypeIndex {
        if (t == 0 or t >= c.typesList.items.len) return t;
        if ((c.typesList.items[t].flags & types.TypeFlags.Void) != 0) {
            c.reportError(node, &diagnostics_gen.An_expression_of_type_void_cannot_be_tested_for_truthiness);
            return t;
        }
        const semantics = getSyntacticTruthySemantics(c, node);
        if (semantics != .Sometimes) {
            if (semantics == .Always) {
                c.reportError(node, &diagnostics_gen.This_kind_of_expression_is_always_truthy);
            } else {
                c.reportError(node, &diagnostics_gen.This_kind_of_expression_is_always_falsy);
            }
        }
        return t;
    }

    pub fn getSyntacticTruthySemantics(c: *Checker, node: ast_gen.NodeIndex) PredicateSemantics {
        _ = c;
        _ = node;
        return .Sometimes; // TODO: Implement getSyntacticTruthySemantics fully
    }

