    /// Port of `checker.go::combineSymbolTables`. Combines two symbol
    /// tables into a new one by merging both into an empty table.
    pub fn combineSymbolTables(c: *Checker, first: ?*const symbol.SymbolTable, second: ?*const symbol.SymbolTable) ?*symbol.SymbolTable {
        if (first == null) return second;
        if (second == null) return first;
        const combined = c.allocator.create(symbol.SymbolTable) catch return first;
        combined.* = .empty;
        c.mergeSymbolTable(combined, first.?, false, 0);
        c.mergeSymbolTable(combined, second.?, false, 0);
        return combined;
    }

    /// Port of `checker.go::mergeSymbolTable`. Merges entries from
    /// `source` into `target`, calling `mergeSymbol` for duplicate keys
    /// and `getMergedSymbol` for new keys. Sets parent on merged symbols
    /// when `mergedParent` is provided.
    pub fn mergeSymbolTable(c: *Checker, target: *symbol.SymbolTable, source: *const symbol.SymbolTable, unidirectional: bool, mergedParent: ast_gen.SymbolIndex) void {
        var it = source.iterator();
        while (it.next()) |entry| {
            const id = entry.key_ptr.*;
            const source_sym = entry.value_ptr.*;
            const target_sym = target.get(id);
            var merged: ast_gen.SymbolIndex = 0;
            if (target_sym) |ts| {
                merged = c.mergeSymbol(ts, source_sym, unidirectional);
                // Set parent on merged transient symbols.
                if (mergedParent != 0 and merged < c.binder.symbols.items.len) {
                    const merged_sym = &c.binder.symbols.items[merged];
                    if ((merged_sym.Flags & symbol.SymbolFlags.Transient) != 0) {
                        merged_sym.Parent = mergedParent;
                    }
                }
            } else {
                merged = getMergedSymbol(c, source_sym);
            }
            // Insert/overwrite into target.
            target.put(c.allocator, id, merged) catch {};
        }
    }

    /// Port of `checker.go::mergeSymbol`. Merges `source` into `target`.
    /// If the flags are compatible, clones target (if non-transient),
    /// merges flags and declarations, and returns the merged symbol.
    /// If incompatible, reports an error and returns `source`.
    pub fn mergeSymbol(c: *Checker, target: ast_gen.SymbolIndex, source: ast_gen.SymbolIndex, unidirectional: bool) ast_gen.SymbolIndex {
        if (target == 0) return source;
        if (source == 0) return target;
        if (target == source) return target;
        if (target >= c.binder.symbols.items.len or source >= c.binder.symbols.items.len) return source;
        const target_sym = c.binder.symbols.items[target];
        const source_sym = c.binder.symbols.items[source];
        // Check if flags are compatible (simplified: check excluded flags).
        const excluded = getExcludedSymbolFlags(source_sym.Flags);
        if ((target_sym.Flags & excluded) != 0 and ((source_sym.Flags | target_sym.Flags) & symbol.SymbolFlags.Assignment) == 0) {
            // Incompatible flags — report error and return source.
            c.reportMergeSymbolError(target, source);
            return source;
        }
        // Compatible — merge flags and declarations.
        // For transient targets, mutate in place. For non-transient, clone.
        const merged_idx = if ((target_sym.Flags & symbol.SymbolFlags.Transient) != 0)
            target
        else
            c.cloneSymbol(target);
        if (merged_idx < c.binder.symbols.items.len) {
            const merged = &c.binder.symbols.items[merged_idx];
            merged.Flags |= source_sym.Flags;
            // Append source declarations to target.
            for (source_sym.Declarations.items) |decl| {
                merged.Declarations.append(c.allocator, decl) catch {};
            }
            // Merge exports and members if both are modules.
            if ((merged.Flags & symbol.SymbolFlags.Module) != 0 and (source_sym.Flags & symbol.SymbolFlags.Module) != 0) {
                if (source_sym.Exports) |src_exports| {
                    if (merged.Exports) |tgt_exports| {
                        c.mergeSymbolTable(tgt_exports, src_exports, unidirectional, merged_idx);
                    } else {
                        merged.Exports = src_exports;
                    }
                }
            }
        }
        return merged_idx;
    }

    /// Port of `checker.go::reportMergeSymbolError`. Reports errors when
    /// merging symbols with incompatible flags (enum, block-scoped, or
    /// duplicate identifier).
    pub fn reportMergeSymbolError(c: *Checker, target: ast_gen.SymbolIndex, source: ast_gen.SymbolIndex) void {
        if (target == 0 or source == 0 or target >= c.binder.symbols.items.len or source >= c.binder.symbols.items.len) return;
        const target_sym = c.binder.symbols.items[target];
        const source_sym = c.binder.symbols.items[source];
        const is_either_enum = (target_sym.Flags & symbol.SymbolFlags.Enum) != 0 or (source_sym.Flags & symbol.SymbolFlags.Enum) != 0;
        const is_either_block_scoped = (target_sym.Flags & symbol.SymbolFlags.BlockScopedVariable) != 0 or (source_sym.Flags & symbol.SymbolFlags.BlockScopedVariable) != 0;
        const msg: *const diagnostics_gen.Message = if (is_either_enum)
            &diagnostics_gen.Enum_declarations_can_only_merge_with_namespace_or_other_enum_declarations
        else if (is_either_block_scoped)
            &diagnostics_gen.Cannot_redeclare_block_scoped_variable_0
        else
            &diagnostics_gen.Duplicate_identifier_0;
        const symbol_name = source_sym.Name;
        // Report on source declarations.
        for (source_sym.Declarations.items) |decl| {
            c.reportErrorWithArgs(decl, msg, &.{symbol_name});
        }
        // Report on target declarations.
        for (target_sym.Declarations.items) |decl| {
            c.reportErrorWithArgs(decl, msg, &.{symbol_name});
        }
    }

    /// Port of `checker.go::addDuplicateDeclarationErrorsForSymbols`.
    /// Reports duplicate declaration errors for each declaration of `target`.
    pub fn addDuplicateDeclarationErrorsForSymbols(c: *Checker, target: ast_gen.SymbolIndex, message: ?*const diagnostics_gen.Message, symbolName: []const u8, source: ast_gen.SymbolIndex) void {
        _ = source;
        if (target == 0 or target >= c.binder.symbols.items.len) return;
        const msg = message orelse &diagnostics_gen.Duplicate_identifier_0;
        const target_sym = c.binder.symbols.items[target];
        for (target_sym.Declarations.items) |decl| {
            c.reportErrorWithArgs(decl, msg, &.{symbolName});
        }
    }

    /// Port of `checker.go::addDuplicateDeclarationError`. Reports a
    /// single duplicate declaration error on `node`.
    pub fn addDuplicateDeclarationError(c: *Checker, node: ast_gen.NodeIndex, message: ?*const diagnostics_gen.Message, symbolName: []const u8, relatedNodes: []const ast_gen.NodeIndex) void {
        const msg = message orelse &diagnostics_gen.Duplicate_identifier_0;
        c.reportErrorWithArgs(node, msg, &.{symbolName});
        // Report related info for each related node (simplified — no chain).
        for (relatedNodes) |related| {
            if (related != 0 and related != node) {
                c.reportErrorWithArgs(related, &diagnostics_gen.X_0_was_also_declared_here, &.{symbolName});
            }
        }
    }

