    pub fn getTargetOfAliasDeclaration(c: *Checker, node: ast_gen.NodeIndex) ast_gen.SymbolIndex {
        // Go: complex — switch on node.Kind calling getTargetOfImportEqualsDeclaration,
        //   getTargetOfImportClause, getTargetOfNamespaceImport, etc.
        // Simplified: dispatch based on kind to the appropriate getTargetOf* method.
        const node_kind = c.binder.ast.getKind(node);
        switch (node_kind) {
            .ImportEqualsDeclaration => return c.getTargetOfImportEqualsDeclaration(node),
            .ImportClause => return c.getTargetOfImportClause(node),
            .NamespaceImport => return c.getTargetOfNamespaceImport(node),
            .NamespaceExport => return c.getTargetOfNamespaceExport(node),
            .ImportSpecifier => return c.getTargetOfImportSpecifier(node),
            .ExportSpecifier => return c.getTargetOfImportSpecifier(node),
            .ExportAssignment => return c.getTargetOfExportAssignment(node),
            .NamespaceExportDeclaration => return c.getTargetOfNamespaceExportDeclaration(node),
            .BinaryExpression => return c.getTargetOfBinaryExpression(node),
            else => return 0,
        }
    }

    /// Port of `checker.go::resolveQualifiedName`. Resolves a qualified
    /// name `left.right` to a symbol by first resolving `left` as a
    /// namespace, then looking up `right` in its exports.
    pub fn resolveQualifiedName(c: *Checker, name_: ast_gen.NodeIndex, left: ast_gen.NodeIndex, right: ast_gen.NodeIndex, meaning: u32, ignoreErrors: bool, location: ast_gen.NodeIndex) ast_gen.SymbolIndex {
        _ = name_;
        _ = ignoreErrors;
        _ = location;
        const namespace = c.resolveEntityName(left, symbol.SymbolFlags.Namespace, true, false, null);
        if (namespace == 0 or namespace == c.unknownSymbol) return namespace;
        if (right == 0) return 0;
        // Get text of `right` (identifier).
        const text = c.binder.ast.getNode(right).Identifier.Text;
        var sym_idx = getMergedSymbol(c, c.getSymbol(c.getExportsOfSymbol(namespace), text, meaning));
        if (sym_idx == 0) {
            // For alias namespaces, try resolving the alias first.
            const ns_sym = c.binder.symbols.items[namespace];
            if ((ns_sym.Flags & symbol.SymbolFlags.Alias) != 0) {
                const resolved_ns = c.resolveAlias(namespace);
                if (resolved_ns != 0) {
                    sym_idx = getMergedSymbol(c, c.getSymbol(c.getExportsOfSymbol(resolved_ns), text, meaning));
                }
            }
        }
        return sym_idx;
    }

    /// Port of `checker.go::tryGetQualifiedNameAsValue`. Resolves a
    /// qualified name as a value by walking from the first identifier
    /// through parent QualifiedName nodes, looking up properties.
    pub fn tryGetQualifiedNameAsValue(c: *Checker, node: ast_gen.NodeIndex) ast_gen.SymbolIndex {
        if (node == 0) return 0;
        // Get the first identifier (leftmost) of the qualified name.
        var id = node;
        while (true) {
            const parent = c.binder.ast.getNodeParent(id);
            if (parent != 0 and c.binder.ast.getKind(parent) == .QualifiedName) {
                id = parent;
            } else break;
        }
        // id is now the leftmost identifier (the start of the qualified name).
        // If id is itself a QualifiedName (e.g. for a.b.c), get its Left.
        if (c.binder.ast.getKind(id) == .QualifiedName) {
            id = c.binder.ast.getNode(id).QualifiedName.Left;
        }
        if (c.binder.ast.getKind(id) != .Identifier) return 0;
        const text = c.binder.ast.getNode(id).Identifier.Text;
        var sym_idx = resolveName(c, id, text, symbol.SymbolFlags.Value, null, true, false);
        if (sym_idx == 0) return 0;
        var n = id;
        while (true) {
            const parent = c.binder.ast.getNodeParent(n);
            if (parent == 0 or c.binder.ast.getKind(parent) != .QualifiedName) break;
            const right = c.binder.ast.getNode(parent).QualifiedName.Right;
            const right_text = c.binder.ast.getNode(right).Identifier.Text;
            const t = c.getTypeOfSymbol(sym_idx) catch return 0;
            sym_idx = c.getPropertyOfType(t, right_text) orelse return 0;
            n = parent;
        }
        return sym_idx;
    }

    /// Port of `checker.go::getSuggestedSymbolForNonexistentModule`.
