    /// Port of `checker.go::instantiateSymbolTable`. Instantiates each
    /// symbol in `symbols` using mapper `m`, returning a new SymbolTable.
    pub fn instantiateSymbolTable(c: *Checker, symbols: *const symbol.SymbolTable, m: types.TypeMapperIndex) ?*symbol.SymbolTable {
        if (m == 0) return null;
        const result = c.allocator.create(symbol.SymbolTable) catch return null;
        result.* = .empty;
        var it = symbols.iterator();
        while (it.next()) |entry| {
            const name = entry.key_ptr.*;
            const sym = entry.value_ptr.*;
            const instantiated = c.instantiateSymbol(sym, m);
            result.put(c.allocator, name, instantiated) catch {};
        }
        return result;
    }

    /// Port of `checker.go::instantiateSymbol`. Instantiates a symbol's
    /// type using mapper `m`. Returns a new transient symbol.
    pub fn instantiateSymbol(c: *Checker, symbol_: ast_gen.SymbolIndex, m: types.TypeMapperIndex) ast_gen.SymbolIndex {
        if (symbol_ == 0 or m == 0) return symbol_;
        if (symbol_ >= c.binder.symbols.items.len) return symbol_;
        // Get the symbol's type, instantiate it, and create a new symbol.
        const t = c.getTypeOfSymbol(symbol_) catch 0;
        if (t == 0) return symbol_;
        const instantiated_type = c.instantiateType(t, m);
        if (instantiated_type == t) return symbol_; // No change.
        // Clone the symbol as transient.
        const new_sym = c.cloneSymbol(symbol_);
        if (new_sym < c.binder.symbols.items.len) {
            c.binder.symbols.items[new_sym].CheckFlags |= types.CheckFlags.Instantiated;
        }
        return new_sym;
    }

    pub fn isThisless(c: *Checker, symbol_: ast_gen.SymbolIndex) bool {
        // Go: if len(symbol.Declarations) == 1 {
        //   declaration := symbol.Declarations[0]
        //   switch declaration.Kind {
        //     case KindParameter: return isThislessVariableLikeDeclaration(declaration)
        //     case KindPropertyDeclaration, KindPropertySignature: return isThislessVariableLikeDeclaration(declaration)
        //     case KindMethodDeclaration, KindMethodSignature, KindConstructor, KindGetAccessor, KindSetAccessor: return isThislessFunctionLikeDeclaration(declaration)
        //   }
        // }
        // return false
        const sym = c.binder.symbols.items[symbol_];
        if (sym.Declarations.items.len != 1) return false;
        const decl = sym.Declarations.items[0];
        if (decl == 0) return false;
        const decl_kind = c.binder.ast.getKind(decl);
        switch (decl_kind) {
            .Parameter, .PropertyDeclaration, .PropertySignature => return isThislessVariableLikeDeclaration(c, decl),
            .MethodDeclaration, .MethodSignature, .Constructor, .GetAccessor, .SetAccessor => return isThislessFunctionLikeDeclaration(c, decl),
            else => return false,
        }
    }

    pub fn isThislessVariableLikeDeclaration(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: typeNode := node.Type(); if typeNode != nil { return isThislessType(typeNode) }; return node.Initializer() == nil
        const type_node: ?ast_gen.NodeIndex = switch (c.binder.ast.getNode(node)) {
            .Parameter => |n| n.Type,
            .VariableDeclaration => |n| n.Type,
            .PropertyDeclaration => |n| n.Type,
            .PropertySignature => |n| n.Type,
            else => null,
        };
        if (type_node) |t| return isThislessType(c, t);
        const initializer: ?ast_gen.NodeIndex = switch (c.binder.ast.getNode(node)) {
            .Parameter => |n| n.Initializer,
            .VariableDeclaration => |n| n.Initializer,
            .PropertyDeclaration => |n| n.Initializer,
            .PropertySignature => |n| n.Initializer,
            else => null,
        };
        return initializer == null;
    }

    pub fn isThislessType(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: switch node.Kind {
        //   case AnyKeyword, UnknownKeyword, StringKeyword, NumberKeyword, BigIntKeyword, BooleanKeyword,
        //     SymbolKeyword, ObjectKeyword, VoidKeyword, UndefinedKeyword, NeverKeyword, LiteralType: return true
        //   case ArrayType: return isThislessType(node.ElementType)
        //   case TypeReference: return core.Every(node.TypeArguments(), isThislessType)
        // }
        // return false
        const node_kind = c.binder.ast.getKind(node);
        switch (node_kind) {
            .AnyKeyword, .UnknownKeyword, .StringKeyword, .NumberKeyword, .BigIntKeyword, .BooleanKeyword,
            .SymbolKeyword, .ObjectKeyword, .VoidKeyword, .UndefinedKeyword, .NeverKeyword, .LiteralType => return true,
            .ArrayType => {
                const elem = c.binder.ast.getNode(node).ArrayType.ElementType;
                return isThislessType(c, elem);
            },
            .TypeReference => {
                const type_args = c.binder.ast.getNode(node).TypeReference.TypeArguments orelse return true;
                const args = c.binder.ast.getNodeList(type_args);
                for (args) |arg| {
                    if (arg != 0 and !isThislessType(c, arg)) return false;
                }
                return true;
            },
            else => return false,
        }
    }

    pub fn isThislessFunctionLikeDeclaration(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: returnType := node.Type()
        //   return (IsConstructorDeclaration(node) || returnType != nil && isThislessType(returnType)) &&
        //     Every(node.Parameters(), isThislessVariableLikeDeclaration) &&
        //     Every(node.TypeParameters(), isThislessTypeParameter)
        const node_kind = c.binder.ast.getKind(node);
        const return_type: ?ast_gen.NodeIndex = switch (c.binder.ast.getNode(node)) {
            .FunctionDeclaration => |n| n.Type,
            .MethodDeclaration => |n| n.Type,
            .Constructor => |n| n.Type,
            .GetAccessor => |n| n.Type,
            .SetAccessor => |n| n.Type,
            else => null,
        };
        const return_ok = ast_utils.isConstructorDeclaration(c.binder.ast, node) or
            (return_type != null and isThislessType(c, return_type.?));
        if (!return_ok) return false;

        const parameters: ?ast_gen.NodeListIndex = switch (c.binder.ast.getNode(node)) {
            .FunctionDeclaration => |n| n.Parameters,
            .MethodDeclaration => |n| n.Parameters,
            .Constructor => |n| n.Parameters,
            .GetAccessor => |n| n.Parameters,
            .SetAccessor => |n| n.Parameters,
            else => null,
        };
        if (parameters) |p| {
            for (c.binder.ast.getNodeList(p)) |param| {
                if (param != 0 and !isThislessVariableLikeDeclaration(c, param)) return false;
            }
        }

        const type_params: ?ast_gen.NodeListIndex = switch (c.binder.ast.getNode(node)) {
            .FunctionDeclaration => |n| n.TypeParameters,
            .MethodDeclaration => |n| n.TypeParameters,
            .Constructor => |n| n.TypeParameters,
            .GetAccessor => |n| n.TypeParameters,
            .SetAccessor => |n| n.TypeParameters,
            else => null,
        };
        if (type_params) |tp| {
            for (c.binder.ast.getNodeList(tp)) |tparam| {
                if (tparam != 0 and !isThislessTypeParameter(c, tparam)) return false;
            }
        }
        _ = node_kind;
        return true;
    }

    pub fn isThislessTypeParameter(c: *Checker, node: ast_gen.NodeIndex) bool {
        // Go: constraint := node.AsTypeParameterDeclaration().Constraint
        //   return constraint == nil || isThislessType(constraint)
        const constraint = c.binder.ast.getNode(node).TypeParameter.Constraint;
        if (constraint == null) return true;
        return isThislessType(c, constraint.?);
    }

    /// Port of `checker.go::getDefaultConstructSignatures`. Returns the
    /// default construct signatures of a class type. If the class has
    /// no explicit constructor, returns a synthetic signature that
    /// constructs the class instance. Conservative: returns 0.
    pub fn getDefaultConstructSignatures(c: *Checker, classType: ast_gen.SymbolIndex) types.SignatureIndex {
        if (classType == 0 or classType >= c.binder.symbols.items.len) return 0;
        // Get the class's declared type and look up construct signatures.
        const declared_type = c.getDeclaredTypeOfSymbol(classType);
        if (declared_type == 0) return 0;
        const sigs = c.getSignaturesOfType(declared_type, .Construct);
        if (sigs.len > 0) return c.resolvedSignaturesPool.items[sigs.start];
        return 0;
    }

    /// Port of `checker.go::getTypeOfMappedSymbol`. Returns the type of
    /// a mapped symbol. For a symbol that's part of a mapped type, returns
    /// the mapped type's value type. Conservative: returns the symbol's
    /// regular type.
    pub fn getTypeOfMappedSymbol(c: *Checker, symbol_: ast_gen.SymbolIndex) types.TypeIndex {
        // Fall back to the regular getTypeOfSymbol.
        return c.getTypeOfSymbol(symbol_) catch 0;
    }

    pub fn getLowerBoundOfKeyType(c: *Checker, t: types.TypeIndex) types.TypeIndex {
        // Returns the lower bound of a key type. For string literal types,
        // returns the string type. For number literal types, returns the
        // number type. For other types, returns `t` unchanged.
        if (t == 0 or t >= c.typesList.items.len) return t;
        const flags = c.typesList.items[t].flags;
        if ((flags & types.TypeFlags.StringLiteral) != 0) return c.stringTypeIndex orelse t;
        if ((flags & types.TypeFlags.NumberLiteral) != 0) return c.numberTypeIndex orelse t;
        return t;
    }

    pub fn getArrayMemberCallSignatures(c: *Checker, t: types.TypeIndex) types.TypeIndex {
        // Returns the call signatures of the element type of an array.
        if (t == 0 or t >= c.typesList.items.len) return 0;
        if (!c.isArrayType(t)) return 0;
        const elem_type = c.getElementTypeOfArrayType(t);
        if (elem_type == 0) return 0;
        const sigs = c.getSignaturesOfType(elem_type, .Call);
        if (sigs.len == 0) return 0;
        return c.resolvedSignaturesPool.items[sigs.start];
    }

    pub fn isArrayOrTupleSymbol(c: *Checker, symbol_: ast_gen.SymbolIndex) bool {
        // Returns true if `symbol_` is an Array or Tuple type symbol.
        if (symbol_ == 0 or symbol_ >= c.binder.symbols.items.len) return false;
        const sym = c.binder.symbols.items[symbol_];
        const name = sym.Name;
        return std.mem.eql(u8, name, "Array") or std.mem.eql(u8, name, "ReadonlyArray") or
            std.mem.eql(u8, name, "Tuple");
    }

    pub fn isReadonlyArraySymbol(c: *Checker, symbol_: ast_gen.SymbolIndex) bool {
        if (symbol_ == 0 or symbol_ >= c.binder.symbols.items.len) return false;
        const sym = c.binder.symbols.items[symbol_];
        return std.mem.eql(u8, sym.Name, "ReadonlyArray");
    }

    pub fn combineUnionOrIntersectionMemberSignatures(c: *Checker, left: types.TypeIndex, right: types.TypeIndex, isUnion: bool) types.TypeIndex {
        // Combines two member signature types. For unions, takes the union;
        // for intersections, takes the intersection.
        if (left == 0) return right;
        if (right == 0) return left;
        const types_arr = [_]types.TypeIndex{ left, right };
        if (isUnion) {
            return c.getUnionTypeFromArray(&types_arr);
        }
        return c.getIntersectionType(&types_arr);
    }

    /// Port of `checker.go::combineUnionOrIntersectionParameters`.
    /// Combines two parameter types using union or intersection.
    pub fn combineUnionOrIntersectionParameters(c: *Checker, left: types.TypeIndex, right: types.TypeIndex, mapper: types.TypeMapperIndex, isUnion: bool) types.TypeIndex {
        const instantiated_left = c.instantiateType(left, mapper);
        const instantiated_right = c.instantiateType(right, mapper);
        if (isUnion) {
            return c.getUnionType(&[_]types.TypeIndex{ instantiated_left, instantiated_right });
        }
        return c.getIntersectionType(&[_]types.TypeIndex{ instantiated_left, instantiated_right });
    }

    /// Port of `checker.go::combineUnionOrIntersectionThisParam`.
    /// Combines two `this` parameter types.
    pub fn combineUnionOrIntersectionThisParam(c: *Checker, left: types.TypeIndex, right: types.TypeIndex, mapper: types.TypeMapperIndex, isUnion: bool) types.TypeIndex {
        return c.combineUnionOrIntersectionParameters(left, right, mapper, isUnion);
    }

