    /// Port of `checker.go::newIntrinsicType`. Creates a new intrinsic type
    /// (e.g. "string", "number") with the given flags.
    pub fn newIntrinsicType(c: *Checker, flags: u32, intrinsicName: []const u8) types.TypeIndex {
