    /// Port of `checker.go::getLiteralTypeFromPropertyName`. Returns the
    /// literal type for a property name node: never for private identifiers,
    /// number literal for numeric literals, string literal for string names,
    /// computed property name type for computed names.
    pub fn getLiteralTypeFromPropertyName(c: *Checker, name: ast_gen.NodeIndex) types.TypeIndex {
        if (name == 0) return c.neverTypeIndex orelse 0;
        const k = c.binder.ast.getKind(name);
        if (k == .PrivateIdentifier) return c.neverTypeIndex orelse 0;
        if (k == .NumericLiteral) {
            const text = c.binder.ast.getNode(name).NumericLiteral.Text;
            const value = std.fmt.parseFloat(f64, text) catch 0.0;
            return c.getRegularTypeOfLiteralType(c.getFreshTypeOfLiteralType(c.getNumberLiteralType(value)));
        }
        if (k == .ComputedPropertyName) {
            return c.getRegularTypeOfLiteralType(c.checkComputedPropertyName(name));
        }
        // String literal or identifier name.
        const text = ast_utils.getTextOfNode(c.binder.ast, name);
        if (text.len > 0) {
            return c.getStringLiteralType(text);
        }
        return c.neverTypeIndex orelse 0;
    }

    /// Port of `checker.go::isKeyTypeIncluded`. Returns true if `keyType`
    /// has any of the `include` flags, or if it's an intersection type
    /// whose constituents include a type with those flags.
    pub fn isKeyTypeIncluded(c: *Checker, key_type: types.TypeIndex, include: u32) bool {
        if (key_type == 0 or key_type >= c.typesList.items.len) return false;
        const flags = c.typesList.items[key_type].flags;
        if ((flags & include) != 0) return true;
        if ((flags & types.TypeFlags.Intersection) != 0) {
            const constituents = c.getTypesFromIntersection(key_type);
            for (constituents) |ct| {
                if (c.isKeyTypeIncluded(ct, include)) return true;
            }
        }
        return false;
    }

    /// Port of `checker.go::checkComputedPropertyName`. Returns the type
    /// of a computed property name expression, reporting an error if the
    /// type is not string/number/symbol/any.
    pub fn checkComputedPropertyName(c: *Checker, node: ast_gen.NodeIndex) types.TypeIndex {
        if (node == 0) return c.errorTypeIndex orelse 0;
        const expr = c.binder.ast.getNode(node).ComputedPropertyName.Expression;
        if (expr == 0) return c.errorTypeIndex orelse 0;
        const t = checkExpression(c, expr);
        if (t == 0) return c.errorTypeIndex orelse 0;
        const flags = c.typesList.items[t].flags;
        // Allow string/number/symbol/any and unions thereof.
        if ((flags & types.TypeFlags.Nullable) != 0) {
            c.reportError(node, &diagnostics_gen.A_computed_property_name_must_be_of_type_string_number_symbol_or_any);
            return c.errorTypeIndex orelse 0;
        }
        if (!c.isTypeAssignableToKind(t, types.TypeFlags.StringLike | types.TypeFlags.NumberLike | types.TypeFlags.ESSymbolLike) and
            !c.isTypeAssignableTo(t, c.stringNumberSymbolType))
        {
            c.reportError(node, &diagnostics_gen.A_computed_property_name_must_be_of_type_string_number_symbol_or_any);
        }
        return t;
    }

    /// Port of `checker.go::isNoInferType`. Returns true if `t` is a
    /// substitution type with an `Unknown` constraint (i.e. `NoInfer<T>`).
    pub fn isNoInferType(c: *Checker, t: types.TypeIndex) bool {
        if (t == 0 or t >= c.typesList.items.len) return false;
        const ty = c.typesList.items[t];
        if (ty.data != .Substitution) return false;
        const constraint_flags = c.typesList.items[ty.data.Substitution.constraint].flags;
        return (constraint_flags & types.TypeFlags.Unknown) != 0;
    }

    /// Port of `checker.go::getSubstitutionIntersection`. For NoInfer types,
    /// returns the base type; otherwise returns the intersection of the
    /// constraint and base type.
    pub fn getSubstitutionIntersection(c: *Checker, t: types.TypeIndex) types.TypeIndex {
        if (t == 0 or t >= c.typesList.items.len) return 0;
        const ty = c.typesList.items[t];
        if (ty.data != .Substitution) return 0;
        if (c.isNoInferType(t)) return ty.data.Substitution.baseType;
        return c.getIntersectionType(&[_]types.TypeIndex{ ty.data.Substitution.constraint, ty.data.Substitution.baseType });
    }

    /// Port of `checker.go::getOrCreateSubstitutionType`. Caches by
